using System; using System.Collections.Generic; using System.Collections.ObjectModel; using System.Collections.Specialized; using System.ComponentModel; using System.Linq; using System.Windows; using System.Windows.Controls; using System.Windows.Controls.Primitives; using System.Windows.Input; using System.Windows.Media; using System.Windows.Media.Imaging; using System.Windows.Shapes; using SunEyeVision.Plugin.SDK.Logging; using SunEyeVision.Plugin.SDK.UI.Controls.Region.Models; using SunEyeVision.Plugin.SDK.UI.Controls.Region.ViewModels; using SunEyeVision.Plugin.SDK.UI.Controls; using SunEyeVision.Plugin.SDK.UI.Controls.Region.Logic; using SunEyeVision.Plugin.SDK.UI.Controls.Region.Rendering; using SunEyeVision.Plugin.SDK.Execution.Parameters;  namespace SunEyeVision.Plugin.SDK.UI.Controls.Region.Views {     /// <summary>     /// 区域编辑控件 - 纯UI组件，不负责数据持久化     /// </summary>     public partial class RegionEditorControl : UserControl, INotifyPropertyChanged     {         private RegionEditorViewModel _viewModel;         private ShapeType _currentTool = ShapeType.Rectangle;         private ImageControl? _mainImageControl;         private Button? _activeShapeButton;          // 控件实例ID（用于区分不同的 RegionEditorControl 实例）         private readonly string _controlInstanceId = Guid.NewGuid().ToString("N").Substring(0, 8);          // 绘制状态         private bool _isDrawing;         private bool _isDragging;         private bool _isDraggingHandle;         private Point _startPoint;         private RegionData? _currentDrawingRegion;         private RegionData? _selectedRegion;         private Point _dragStartPoint;         private Point _handleDragStartPoint;          // 多边形绘制状态         private bool _isDrawingPolygon;         private readonly List<Point> _polygonPoints = new();         private int _activeVertexIndex = -1;         private const string RubberBandTag = "PolygonRubberBand";          // 记录上次鼠标位置（用于多边形删除后临时顶点预览）         private Point _lastMouseImagePosition;          // 日志监控计数器         private int _mouseMoveLogCounter = 0;         private int _drawingLogCount = 0;         private int _previewLogCount = 0;         private int _renderLogCount = 0;          // 区域名称索引管理（空洞池策略）         private int _nextRegionIndex = 1;         private readonly SortedSet<int> _availableIndices = new();          // 手柄管理         private HandleManager _handleManager;         private RegionEditorSettings _settings;          // ROI编辑器风格的手柄管理         private Rendering.EditHandle[] _currentHandles = null;         private Rendering.HandleType _activeHandleType = Rendering.HandleType.None;         private ShapeParameters? _originalShapeDefinition = null;         private Point _originalPosition;         private Size _originalSize;         private double _originalRotation;         private double? _rotateStartAngle = null;         private double? _rotateStartMouseAngle = null;          // WPF Shape渲染器（对象池 + 增量更新）         private WpfShapeRenderer? _renderer;          public RegionEditorViewModel ViewModel => _viewModel;          /// <summary>         /// 获取InteractionOverlayCanvas（ROI交互层）         /// </summary>         private Canvas? OverlayCanvas => _mainImageControl?.InteractionOverlayCanvasControl;          #region 依赖属性          /// <summary>         /// 区域数据集合（仅用于 XAML 声明式绑定初始化读取）         /// </summary>         /// <remarks>         /// 此 DependencyProperty 仅作为 XAML 绑定的桥接层。         /// 真正的共享引用由 SetRegionsSource() 方法命令式建立。         /// 不要依赖此属性的变更回调来建立共享引用。         /// </remarks>         public static readonly DependencyProperty RegionsProperty =             DependencyProperty.Register(nameof(Regions), typeof(IEnumerable<RegionData>), typeof(RegionEditorControl),                 new PropertyMetadata(null, OnRegionsChanged));          public IEnumerable<RegionData>? Regions         {             get => (IEnumerable<RegionData>?)GetValue(RegionsProperty);             set => SetValue(RegionsProperty, value);         }          private static void OnRegionsChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)         {             if (d is RegionEditorControl control)             {                 // 仅更新渲染，不建立共享引用                 // 共享引用由 SetRegionsSource() 方法显式建立                 control.UpdateRegionOverlay();             }         }          /// <summary>         /// AvailableDataSources 透传属性（用于内部 RegionSubscribePanel）         /// </summary>         public static readonly DependencyProperty AvailableDataSourcesProperty =             DependencyProperty.Register(nameof(AvailableDataSources),                 typeof(System.Collections.ObjectModel.ObservableCollection<AvailableDataSource>),                 typeof(RegionEditorControl),                 new PropertyMetadata(null));          public System.Collections.ObjectModel.ObservableCollection<AvailableDataSource>? AvailableDataSources         {             get => (System.Collections.ObjectModel.ObservableCollection<AvailableDataSource>?)GetValue(AvailableDataSourcesProperty);             set => SetValue(AvailableDataSourcesProperty, value);         }          #endregion          #region 事件          /// <summary>         /// 区域数据变更事件         /// </summary>         public event EventHandler<RegionData>? RegionDataChanged;          #endregion          #region 共享引用管理          /// <summary>         /// 注入外部区域集合，与参数模型共享同一个 ObservableCollection 实例         /// </summary>         /// <remarks>         /// 这是建立共享引用的唯一正确入口。         /// 调用后 ViewModel.Regions 和外部集合指向同一个对象，         /// 用户绘制区域直接进入参数集合，序列化时自然有数据。         ///          /// 必须在 SetMainImageControl 之后调用。         /// </remarks>         public void SetRegionsSource(ObservableCollection<RegionData> externalRegions)         {             if (externalRegions == null)                 throw new ArgumentNullException(nameof(externalRegions));              VisionLogger.Instance.Log(LogLevel.Info,                 $"[SetRegionsSource] 建立共享引用 | 外部集合HashCode={externalRegions.GetHashCode():X8} | 外部集合数量={externalRegions.Count}",                 "RegionEditorControl");              _viewModel.SetRegionsSource(externalRegions);             InitializeRegionIndexFromExisting();             UpdateRegionOverlay();              VisionLogger.Instance.Log(LogLevel.Success,                 $"[SetRegionsSource] 共享引用已建立 | ViewModel.Regions={_viewModel.Regions.GetHashCode():X8} | 引用相同={_viewModel.Regions == externalRegions}",                 "RegionEditorControl");         }          #endregion          public RegionEditorControl()         {             // 设计时跳过初始化             if (DesignerProperties.GetIsInDesignMode(this))             {                 InitializeComponent();                 EnsureViewModel();                 _handleManager = new HandleManager();                 _settings = RegionEditorSettings.Default;                 return;             }              InitializeComponent();             EnsureViewModel();             _handleManager = new HandleManager();             _settings = RegionEditorSettings.Default;              // 启用键盘焦点             Focusable = true;             FocusVisualStyle = null;              // 绑定键盘快捷键和生命周期事件             Loaded += RegionEditorControl_Loaded;             Unloaded += RegionEditorControl_Unloaded;              VisionLogger.Instance.Log(LogLevel.Success,                 $"[RegionEditorControl] 控件初始化完成 | InstanceId={_controlInstanceId}",                 "RegionEditorControl");         }          private void RegionEditorControl_Loaded(object sender, RoutedEventArgs e)         {             VisionLogger.Instance.Log(LogLevel.Success,                 $"[RegionEditorControl] 控件已加载（Tab切换）| InstanceId={_controlInstanceId}",                 "RegionEditorControl");              Keyboard.Focus(this);              // 确保 ImageControl 引用和渲染器状态有效             if (_mainImageControl != null && OverlayCanvas != null)             {                 // 如果渲染器已被销毁（异常情况），重新创建                 if (_renderer == null)                 {                     _renderer = new WpfShapeRenderer(OverlayCanvas, VisionLogger.Instance);                     VisionLogger.Instance.Log(LogLevel.Info,                         $"[RegionEditorControl_Loaded] 重新创建渲染器 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                 }                  // 更新区域覆盖层（确保区域可见）                 UpdateRegionOverlay();                 VisionLogger.Instance.Log(LogLevel.Success,                     $"[RegionEditorControl_Loaded] 渲染状态已恢复 | InstanceId={_controlInstanceId} | RegionCount={_viewModel.Regions.Count}",                     "RegionEditorControl");             }             else if (_mainImageControl == null)             {                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[RegionEditorControl_Loaded] ImageControl 引用为空，无法恢复渲染 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");                  // ⚠️ 时序问题修复：如果渲染器已存在但 ImageControl 为空，                 // 说明是时序问题（SetMainImageControl 晚于 Loaded 触发）。                 // 标记需要恢复渲染，稍后 SetMainImageControl 会处理。                 if (_renderer != null && _viewModel.Regions.Count > 0)                 {                     VisionLogger.Instance.Log(LogLevel.Info,                         $"[RegionEditorControl_Loaded] 检测到时序问题：渲染器已存在但 ImageControl 为空，将在 SetMainImageControl 时恢复渲染 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                 }             }         }          private void RegionEditorControl_Unloaded(object sender, RoutedEventArgs e)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[RegionEditorControl] 控件已卸载（Tab切换）| InstanceId={_controlInstanceId} | _mainImageControl={_mainImageControl?.GetType().Name ?? "null"} | _isDrawing={_isDrawing}",                 "RegionEditorControl");              // ⚠️ 不调用 ClearMainOverlay()，保留 ImageControl 引用和事件订阅             // 绘制操作发生在主窗口的 ImageControl 上，不应受 Tab 切换影响              // 如果正在绘制中，取消绘制状态（避免切换 Tab 时绘制状态不一致）             if (_isDrawing)             {                 _isDrawing = false;                 _currentDrawingRegion = null;                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[RegionEditorControl_Unloaded] Tab切换时取消绘制状态 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");             }         }          /// <summary>         /// 确保 ViewModel 已创建（懒加载）         /// </summary>         private void EnsureViewModel()         {             if (_viewModel == null)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     "[EnsureViewModel] 创建新的 ViewModel 实例",                     "RegionEditorControl");                  _viewModel = new RegionEditorViewModel();                 DataContext = _viewModel;                  // ★ 订阅 ViewModel 事件（在整个生命周期内保持订阅）                 // 事件订阅生命周期由 SetMainImageControl / ClearMainOverlay 管理                 // Tab 切换不应该影响订阅状态                 _viewModel.PropertyChanged += OnViewModelPropertyChanged;                 _viewModel.RegionChanged += OnRegionChanged;                  // 不再订阅 Regions.CollectionChanged，共享引用后无需同步                  VisionLogger.Instance.Log(LogLevel.Success,                     "[EnsureViewModel] ViewModel 创建并初始化完成",                     "RegionEditorControl");             }             else             {                 VisionLogger.Instance.Log(LogLevel.Info,                     "[EnsureViewModel] ViewModel 已存在，跳过创建",                     "RegionEditorControl");             }         }            /// <summary>         /// 设置主界面ImageControl引用         /// </summary>         public void SetMainImageControl(ImageControl imageControl)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[SetMainImageControl] 设置 ImageControl | InstanceId={_controlInstanceId} | Old={_mainImageControl?.GetType().Name ?? "null"} | New={imageControl?.GetType().Name ?? "null"}",                 "RegionEditorControl");              // 如果是同一个实例，不做任何操作             if (_mainImageControl == imageControl)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[SetMainImageControl] 相同 ImageControl，跳过设置 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");                 return;             }              // 先取消旧的事件订阅             if (_mainImageControl != null)             {                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[EventUnsubscribe] 取消旧 ImageControl 的事件订阅 | InstanceId={_controlInstanceId} | ImageControl={_mainImageControl.GetType().Name}",                     "RegionEditorControl");                  _mainImageControl.ImageMouseMove -= ImageControl_ImageMouseMove;                 _mainImageControl.ViewTransformed -= ImageControl_ViewTransformed;                 _mainImageControl.CanvasMouseLeftButtonDown -= ImageControl_CanvasMouseLeftButtonDown;                 _mainImageControl.CanvasMouseLeftButtonUp -= ImageControl_CanvasMouseLeftButtonUp;                  VisionLogger.Instance.Log(LogLevel.Success,                     $"[EventUnsubscribe] 已取消 ImageControl 事件订阅 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");             }              // 设置新的引用             _mainImageControl = imageControl;              if (_mainImageControl != null)             {                 // 禁用OverlayCanvas命中测试（手柄/区域命中检测使用手动坐标计算，不需要WPF命中测试）                 // 设为false可避免OverlayCanvas上的形状拦截鼠标事件，确保MouseUp事件正确传到MainCanvas                 _mainImageControl.OverlayHitTestVisible = false;                  VisionLogger.Instance.Log(LogLevel.Info,                     $"[EventSubscribe] 开始订阅 ImageControl 事件 | InstanceId={_controlInstanceId} | ImageControl={_mainImageControl.GetType().Name}",                     "RegionEditorControl");                  // 订阅ImageControl事件（不依赖视觉树）                 _mainImageControl.ImageMouseMove += ImageControl_ImageMouseMove;                 VisionLogger.Instance.Log(LogLevel.Success,                     $"[EventSubscribe] 已订阅 ImageMouseMove 事件 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");                  _mainImageControl.ViewTransformed += ImageControl_ViewTransformed;                 VisionLogger.Instance.Log(LogLevel.Success,                     $"[EventSubscribe] 已订阅 ViewTransformed 事件 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");                  _mainImageControl.CanvasMouseLeftButtonDown += ImageControl_CanvasMouseLeftButtonDown;                 VisionLogger.Instance.Log(LogLevel.Success,                     $"[EventSubscribe] 已订阅 CanvasMouseLeftButtonDown 事件 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");                  _mainImageControl.CanvasMouseLeftButtonUp += ImageControl_CanvasMouseLeftButtonUp;                 VisionLogger.Instance.Log(LogLevel.Success,                     $"[EventSubscribe] 已订阅 CanvasMouseLeftButtonUp 事件 | InstanceId={_controlInstanceId}",                     "RegionEditorControl");                  // 订阅窗口级 MouseUp 事件（兜底：处理鼠标移出 MainCanvas 后松开的边界情况）                 var window = Window.GetWindow(_mainImageControl);                 if (window != null)                 {                     window.AddHandler(Window.MouseLeftButtonUpEvent, new MouseButtonEventHandler(Window_MouseLeftButtonUp));                     window.AddHandler(Window.MouseRightButtonDownEvent, new MouseButtonEventHandler(Window_MouseRightButtonDown));                     VisionLogger.Instance.Log(LogLevel.Success,                         $"[EventSubscribe] 已订阅窗口级 MouseUp + MouseRightButtonDown 事件 | InstanceId={_controlInstanceId} | Window={window.GetType().Name}",                         "RegionEditorControl");                 }                 else                 {                     VisionLogger.Instance.Log(LogLevel.Warning,                         $"[EventSubscribe] 警告：无法获取 Window，跳过订阅窗口级事件 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                 }                  // 初始化WPF Shape渲染器                 if (OverlayCanvas != null)                 {                     _renderer?.Dispose();                     _renderer = new WpfShapeRenderer(OverlayCanvas, VisionLogger.Instance);                      // ★ 关键修复：初始化时立即同步当前缩放值                     // 否则 _viewportScale 默认为 1.0（而非当前 zoom），                     // 导致首次渲染时线宽 = rawStroke / 1.0 = 太粗                     _renderer?.SetViewportTransform(_mainImageControl.Zoom, new Point(0, 0));                 }                  VisionLogger.Instance.Log(LogLevel.Success,                     $"[SetMainImageControl] 已设置 ImageControl 并订阅所有事件 | InstanceId={_controlInstanceId} | OverlayCanvas={OverlayCanvas != null} | IsDrawing={_viewModel.IsDrawing} | _isDrawing={_isDrawing}",                     "RegionEditorControl");             }              UpdateRegionOverlay();         }          /// <summary>         /// 清理主界面覆盖层和所有事件订阅         /// </summary>         public void ClearMainOverlay()         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[ClearMainOverlay] 清理主界面覆盖层和所有事件订阅 | InstanceId={_controlInstanceId}",                 "RegionEditorControl");              try             {                 // 取消 ImageControl 事件订阅                 if (_mainImageControl != null)                 {                     VisionLogger.Instance.Log(LogLevel.Info,                         $"[EventUnsubscribe] 取消 ImageControl 事件订阅 | InstanceId={_controlInstanceId} | ImageControl={_mainImageControl.GetType().Name}",                         "RegionEditorControl");                      _mainImageControl.ImageMouseMove -= ImageControl_ImageMouseMove;                     VisionLogger.Instance.Log(LogLevel.Success,                         $"[EventUnsubscribe] 已取消 ImageMouseMove 事件订阅 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                      _mainImageControl.ViewTransformed -= ImageControl_ViewTransformed;                     VisionLogger.Instance.Log(LogLevel.Success,                         $"[EventUnsubscribe] 已取消 ViewTransformed 事件订阅 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                      _mainImageControl.CanvasMouseLeftButtonDown -= ImageControl_CanvasMouseLeftButtonDown;                     VisionLogger.Instance.Log(LogLevel.Success,                         $"[EventUnsubscribe] 已取消 CanvasMouseLeftButtonDown 事件订阅 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                      _mainImageControl.CanvasMouseLeftButtonUp -= ImageControl_CanvasMouseLeftButtonUp;                     VisionLogger.Instance.Log(LogLevel.Success,                         $"[EventUnsubscribe] 已取消 CanvasMouseLeftButtonUp 事件订阅 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                      // 取消窗口级事件订阅                     var window = Window.GetWindow(_mainImageControl);                     if (window != null)                     {                         window.RemoveHandler(Window.MouseLeftButtonUpEvent, new MouseButtonEventHandler(Window_MouseLeftButtonUp));                         window.RemoveHandler(Window.MouseRightButtonDownEvent, new MouseButtonEventHandler(Window_MouseRightButtonDown));                         VisionLogger.Instance.Log(LogLevel.Success,                             $"[EventUnsubscribe] 已取消窗口级事件订阅 | InstanceId={_controlInstanceId} | Window={window.GetType().Name}",                             "RegionEditorControl");                     }                 }                  // 取消 ViewModel 事件订阅                 if (_viewModel != null)                 {                     VisionLogger.Instance.Log(LogLevel.Info,                         $"[EventUnsubscribe] 取消 ViewModel 事件订阅 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                      _viewModel.PropertyChanged -= OnViewModelPropertyChanged;                     _viewModel.RegionChanged -= OnRegionChanged;                     // 不再退订 Regions.CollectionChanged，已删除订阅                      VisionLogger.Instance.Log(LogLevel.Success,                         $"[EventUnsubscribe] 已取消 ViewModel 事件订阅 | InstanceId={_controlInstanceId}",                         "RegionEditorControl");                 }                  // 不再调用 UnsubscribeFromExternalRegions，已删除该方法                  // 清理覆盖层                 if (_mainImageControl != null)                 {                     // 恢复只读模式：调试窗口关闭后不允许编辑ROI                     _mainImageControl.OverlayHitTestVisible = false;                     _mainImageControl.InteractionOverlayCanvasControl.Children.Clear();                 }                  // 清理渲染器                 _renderer?.Dispose();                 _renderer = null;                  // 清理引用                 _mainImageControl = null;                  VisionLogger.Instance.Log(LogLevel.Success,                     "[ClearMainOverlay] 清理完成",                     "RegionEditorControl");             }             catch (Exception ex)             {                 VisionLogger.Instance.Log(LogLevel.Error,                     $"[ClearMainOverlay] 清理失败: {ex.Message}",                     "RegionEditorControl",                     ex);             }         }          /// <summary>         /// 加载图像         /// </summary>         public void LoadImage(BitmapSource image)         {             if (_mainImageControl != null)             {                 _mainImageControl.SourceImage = image;             }         }          /// <summary>         /// 获取所有区域数据         /// </summary>         public IEnumerable<RegionData> GetRegions()         {             return _viewModel.Regions;         }          /// <summary>         /// 获取选中的区域         /// </summary>         public RegionData? GetSelectedRegion()         {             return _selectedRegion;         }          /// <summary>         /// 设置选中的区域         /// </summary>         public void SetSelectedRegion(RegionData? region)         {             SelectRegion(region);         }          /// <summary>         /// 添加区域         /// </summary>         public void AddRegion(RegionData region)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[AddRegion] 添加区域: RegionId={region.Id}, RegionType={region.GetShapeType()?.ToString() ?? "Unknown"}",                 "RegionEditorControl");              try             {                 _viewModel.Regions.Add(region);                 UpdateRegionOverlay();                 // RegionChanged 事件会通过 OnRegionChanged 自动转发到 RegionDataChanged                 // 这里不再手动触发，避免重复通知             }             catch (Exception ex)             {                 VisionLogger.Instance.Log(LogLevel.Error,                     $"[AddRegion] 添加区域失败: RegionId={region.Id}, 错误={ex.Message}",                     "RegionEditorControl",                     ex);             }         }          /// <summary>         /// 移除区域         /// </summary>         public void RemoveRegion(RegionData region)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[RemoveRegion] 移除区域: RegionId={region.Id}, RegionType={region.GetShapeType()?.ToString() ?? "Unknown"}",                 "RegionEditorControl");              try             {                 _viewModel.Regions.Remove(region);                 if (_selectedRegion == region)                 {                     UnsubscribeShapeParameters(_selectedRegion);                     _selectedRegion = null;                 }                 UpdateRegionOverlay();                 // RegionChanged 事件会通过 OnRegionChanged 自动转发到 RegionDataChanged                 // 这里不再手动触发，避免重复通知             }             catch (Exception ex)             {                 VisionLogger.Instance.Log(LogLevel.Error,                     $"[RemoveRegion] 移除区域失败: RegionId={region.Id}, 错误={ex.Message}",                     "RegionEditorControl",                     ex);             }         }          /// <summary>         /// 解析所有区域         /// </summary>         public List<Logic.ResolvedRegion> ResolveAllRegions()         {             return _viewModel.ResolveAllRegions();         }          #region 键盘快捷键          /// <summary>         /// 处理键盘按键         /// </summary>         protected override void OnPreviewKeyDown(KeyEventArgs e)         {             base.OnPreviewKeyDown(e);              // Ctrl+Z: 撤销             if (e.Key == Key.Z && (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)             {                 if (_viewModel.CanUndo)                 {                     _viewModel.Undo();                     UpdateRegionOverlay();                     e.Handled = true;                 }                 return;             }              // Ctrl+Y: 重做             if (e.Key == Key.Y && (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)             {                 if (_viewModel.CanRedo)                 {                     _viewModel.Redo();                     UpdateRegionOverlay();                     e.Handled = true;                 }                 return;             }              // Delete: 删除选中区域             if (e.Key == Key.Delete && _selectedRegion != null)             {                 // ★ 诊断日志：删除前状态                 var beforeRegionNames = string.Join(", ", _viewModel.Regions.Select(r => $"{r.Name}(Id={r.Id:B})"));                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[Delete] 删除前状态 | InstanceId={_controlInstanceId} | 删除目标={_selectedRegion.Name}(Id={_selectedRegion.Id:B}) | Regions.Count={_viewModel.Regions.Count} | Regions=[{beforeRegionNames}] | _selectedRegion={_selectedRegion.Name}",                     "RegionEditorControl");                  _viewModel.RemoveSelectedRegion();                  // ★ 诊断日志：删除后状态（ViewModel 内部已触发 RegionChanged → OnRegionChanged → UpdateRegionOverlay）                 var afterRegionNames = string.Join(", ", _viewModel.Regions.Select(r => $"{r.Name}(Id={r.Id:B})"));                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[Delete] ViewModel.RemoveSelectedRegion 完成 | Regions.Count={_viewModel.Regions.Count} | Regions=[{afterRegionNames}] | SelectedRegion={_viewModel.SelectedRegion?.Name ?? "null"}",                     "RegionEditorControl");                  UnsubscribeShapeParameters(_selectedRegion);                 _selectedRegion = null;                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[Delete] 开始第二次 UpdateRegionOverlay | _selectedRegion=null | Regions.Count={_viewModel.Regions.Count}",                     "RegionEditorControl");                  UpdateRegionOverlay();                 e.Handled = true;                 return;             }              // Escape: 取消当前操作             if (e.Key == Key.Escape)             {                 if (_isDrawingPolygon)                 {                     _isDrawingPolygon = false;                     _polygonPoints.Clear();                     if (_currentDrawingRegion != null)                         ReleaseRegionIndex(_currentDrawingRegion.Name);                     _currentDrawingRegion = null;                     ClearRubberBand();                     UpdateRegionOverlay();                     _viewModel.StatusMessage = "已取消多边形绘制";                 }                 else if (_isDrawing)                 {                     _isDrawing = false;                     _currentDrawingRegion = null;                     UpdateRegionOverlay();                     _viewModel.StatusMessage = "已取消绘制";                 }                 else if (_isDragging || _isDraggingHandle)                 {                     _isDragging = false;                     _isDraggingHandle = false;                     UpdateRegionOverlay();                     _viewModel.StatusMessage = "已取消编辑";                 }                 else                 {                     DeselectAll();                 }                 e.Handled = true;                 return;             }              // Enter: 完成多边形             if (e.Key == Key.Enter && _isDrawingPolygon                 && _currentTool == ShapeType.Polygon && _polygonPoints.Count >= 3)             {                 _isDrawingPolygon = false;                 FinishInteraction();                 e.Handled = true;                 return;             }              // Backspace: 撤销多边形最后一个顶点             if (e.Key == Key.Back && _isDrawingPolygon                 && _currentTool == ShapeType.Polygon && _polygonPoints.Count > 0)             {                 _polygonPoints.RemoveAt(_polygonPoints.Count - 1);                 SyncPolygonToShapeDef();                 if (_polygonPoints.Count == 0)                 {                     _isDrawingPolygon = false;                     if (_currentDrawingRegion != null)                         ReleaseRegionIndex(_currentDrawingRegion.Name);                     _currentDrawingRegion = null;                 }                 ClearRubberBand();                 if (_polygonPoints.Count >= 1 && _currentDrawingRegion != null)                 {                     // 插入上次鼠标位置作为临时点，避免预览跳变                     if (_currentDrawingRegion.Parameters is ShapeParameters shapeDef)                     {                         shapeDef.Points.Add(new Point2D(_lastMouseImagePosition.X, _lastMouseImagePosition.Y));                         UpdateSingleRegionFast(_currentDrawingRegion);                         shapeDef.Points.RemoveAt(shapeDef.Points.Count - 1);                     }                 }                 else if (_polygonPoints.Count == 0)                     UpdateRegionOverlay();  // 全量重建，清除残留名称标签                 _viewModel.StatusMessage = _polygonPoints.Count > 0                     ? $"多边形顶点: {_polygonPoints.Count}"                     : "已取消多边形绘制";                 e.Handled = true;                 return;             }              // 快捷键选择形状工具             if (_viewModel.IsDrawingMode)             {                 switch (e.Key)                 {                     case Key.V:                         EnterSelectMode(null);                         e.Handled = true;                         break;                     case Key.R:                         SelectShapeTool(ShapeType.Rectangle, null);                         e.Handled = true;                         break;                     case Key.C:                         SelectShapeTool(ShapeType.Circle, null);                         e.Handled = true;                         break;                     case Key.O:                         SelectShapeTool(ShapeType.RotatedRectangle, null);                         e.Handled = true;                         break;                     case Key.L:                         SelectShapeTool(ShapeType.Line, null);                         e.Handled = true;                         break;                     case Key.P:                         _isDrawingPolygon = false;                         SelectShapeTool(ShapeType.Polygon, null);                         e.Handled = true;                         break;                 }             }             else             {                 // 非绘制模式下，V键也可以切换到选择模式                 if (e.Key == Key.V)                 {                     EnterSelectMode(null);                     e.Handled = true;                 }             }         }          #endregion          #region 鼠标事件处理          private void ImageControl_ImageMouseMove(object? sender, ImageMouseEventArgs e)         {             if (OverlayCanvas == null) return;              var position = e.ImagePosition;             _lastMouseImagePosition = position;              // 每100次移动记录一次日志，避免日志过多             if (_mouseMoveLogCounter++ % 100 == 0)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[MouseMove] Count={_mouseMoveLogCounter} | Position={position:F1} | IsDrawing={_isDrawing} | IsDragging={_isDragging} | IsDraggingHandle={_isDraggingHandle}",                     "RegionEditorControl");             }              // 拖动ROI编辑器风格的手柄编辑             if (_isDraggingHandle && _activeHandleType != Rendering.HandleType.None && _selectedRegion?.Parameters is ShapeParameters shape)             {                 HandleShapeEdit(shape, position);                 UpdateSingleRegionFast(_selectedRegion);                 return;             }              // 拖动区域             if (_isDragging && _selectedRegion != null)             {                 var offset = position - _dragStartPoint;                 MoveRegion(_selectedRegion, offset);                 _dragStartPoint = position;                 UpdateSingleRegionFast(_selectedRegion);                 return;             }              // 绘制预览             if (_isDrawing && _currentDrawingRegion != null)             {                 // 多边形预览：临时加入鼠标位置做填充预览                 if (_currentTool == ShapeType.Polygon && _isDrawingPolygon)                 {                 if (_polygonPoints.Count >= 1)                 {                     if (_currentDrawingRegion.Parameters is ShapeParameters shapeDef)                     {                         shapeDef.Points.Add(new Point2D(position.X, position.Y));                         UpdateSingleRegionFast(_currentDrawingRegion);                         shapeDef.Points.RemoveAt(shapeDef.Points.Count - 1);                     }                 }                 DrawPolygonRubberBand(position);                 }                 else                 {                     // 首次更新时记录日志                     if (_drawingLogCount == 0)                     {                         VisionLogger.Instance.Log(LogLevel.Info,                             $"[绘制预览] 开始更新预览 | CurrentDrawingRegion={_currentDrawingRegion.Name} | Position={position:F1}",                             "RegionEditorControl");                         _drawingLogCount++;                     }                      UpdateDrawingPreview(position);                     UpdateSingleRegionFast(_currentDrawingRegion);                 }             }         }          private void ImageControl_CanvasMouseLeftButtonDown(object? sender, ImageMouseEventArgs e)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[CanvasMouseLeftButtonDown] MouseDown事件 | InstanceId={_controlInstanceId} | IsDrawing={_viewModel.IsDrawing} | _isDrawing={_isDrawing} | Tool={_currentTool} | Position={e.ImagePosition:F1} | OverlayCanvas={OverlayCanvas != null}",                 "RegionEditorControl");              if (OverlayCanvas == null) return;              var position = e.ImagePosition;              // ========== 多边形绘制模式 ==========             if (_currentTool == ShapeType.Polygon)             {                 // 双击完成（从原始事件中获取 ClickCount）                 var clickCount = (e.OriginalEventArgs as MouseButtonEventArgs)?.ClickCount ?? 1;                 if (clickCount >= 2 && _polygonPoints.Count >= 3)                 {                     _isDrawingPolygon = false;                     FinishInteraction();                     e.Handled = true;                     return;                 }                  // 首次点击：初始化                 if (!_isDrawingPolygon)                 {                     _isDrawingPolygon = true;                     _isDrawing = true;                     _polygonPoints.Clear();                     _currentDrawingRegion = RegionData.CreateDrawingRegion(                         GenerateRegionName(), _currentTool);                     _currentDrawingRegion.IsPreview = true;                 }                  // 添加顶点 + 同步                 _polygonPoints.Add(position);                 SyncPolygonToShapeDef();                 ClearRubberBand();                 // ★ 统一使用增量更新，与右键/Backspace/mouseMove 保持一致                 UpdateSingleRegionFast(_currentDrawingRegion);                 _viewModel.StatusMessage = $"多边形顶点: {_polygonPoints.Count}";                 e.Handled = true;                 return;             }              // ========== 绘制模式 ==========             if (_viewModel.IsDrawing && _currentTool != ShapeType.Point)             {                 VisionLogger.Instance.Log(LogLevel.Success,                     $"[开始绘制] 进入绘制流程 | InstanceId={_controlInstanceId} | Tool={_currentTool} | Position={position:F1} | _isDrawing={_isDrawing} | _nextRegionIndex={_nextRegionIndex} | 空洞池数量={_availableIndices.Count}",                     "RegionEditorControl");                  // 检查是否已经在绘制中，防止重复触发                 if (_isDrawing)                 {                     VisionLogger.Instance.Log(LogLevel.Warning,                         $"[开始绘制] 警告：已在绘制中，忽略重复触发 | InstanceId={_controlInstanceId} | CurrentDrawingRegion={_currentDrawingRegion?.Name ?? "null"}",                         "RegionEditorControl");                     e.Handled = true;                     return;                 }                  // 开始绘制                 _isDrawing = true;                 _startPoint = position;                  _currentDrawingRegion = RegionData.CreateDrawingRegion(                     GenerateRegionName(),                     _currentTool                 );                  VisionLogger.Instance.Log(LogLevel.Info,                     $"[开始绘制] 创建绘制区域 | InstanceId={_controlInstanceId} | RegionName={_currentDrawingRegion?.Name ?? "null"} | IsPreview={_currentDrawingRegion?.IsPreview} | _nextRegionIndex={_nextRegionIndex}",                     "RegionEditorControl");                  if (_currentDrawingRegion.Parameters is ShapeParameters shapeDef)                 {                     switch (_currentTool)                     {                         case ShapeType.Rectangle:                         case ShapeType.RotatedRectangle:                             shapeDef.CenterX = position.X;                             shapeDef.CenterY = position.Y;                             shapeDef.Width = 0;                             shapeDef.Height = 0;                             break;                         case ShapeType.Circle:                             shapeDef.CenterX = position.X;                             shapeDef.CenterY = position.Y;                             shapeDef.Radius = 0;                             shapeDef.Width = 0;                             shapeDef.Height = 0;                             break;                         case ShapeType.Line:                             shapeDef.StartX = position.X;                             shapeDef.StartY = position.Y;                             shapeDef.EndX = position.X;                             shapeDef.EndY = position.Y;                             break;                     }                 }                  e.Handled = true;                 return;             }              // ========== 非绘制模式（选择/编辑） ==========             // 首先检测是否命中手柄（仅当有选中区域时）             if (_selectedRegion != null)             {                 if (_currentHandles != null)                 {                     var hitHandleType = Rendering.HandleRenderer.HitTestHandle(position, _currentHandles);                      if (hitHandleType != Rendering.HandleType.None)                     {                         // 中心手柄：触发拖动                         if (hitHandleType == Rendering.HandleType.Center)                         {                             _isDragging = true;                             _dragStartPoint = position;                             _viewModel.StatusMessage = "正在拖动区域";                             e.Handled = true;                             return;                         }                          // 多边形顶点手柄                         if (hitHandleType == Rendering.HandleType.PolygonVertex)                         {                             _isDraggingHandle = true;                             _activeHandleType = hitHandleType;                             _handleDragStartPoint = position;                              // 找到被命中手柄的顶点索引                             _activeVertexIndex = -1;                             if (_currentHandles != null)                             {                                 foreach (var h in _currentHandles)                                 {                                     if (h.Type == Rendering.HandleType.PolygonVertex && h.VertexIndex >= 0)                                     {                                         var dx = position.X - h.Position.X;                                         var dy = position.Y - h.Position.Y;                                         if (Math.Sqrt(dx * dx + dy * dy) < h.HandleSize)                                         {                                             _activeVertexIndex = h.VertexIndex;                                             break;                                         }                                     }                                 }                             }                              if (_selectedRegion?.Parameters is ShapeParameters polyShape)                                 _originalShapeDefinition = polyShape.Clone() as ShapeParameters;                              _viewModel.StatusMessage = "正在拖拽多边形顶点";                             e.Handled = true;                             return;                         }                          // 其他手柄：开始编辑                         _isDraggingHandle = true;                         _activeHandleType = hitHandleType;                         _handleDragStartPoint = position;                          // 保存原始状态                         if (_selectedRegion.Parameters is ShapeParameters shapeDef)                         {                             _originalShapeDefinition = shapeDef.Clone() as ShapeParameters;                             _originalPosition = new Point(shapeDef.CenterX, shapeDef.CenterY);                             _originalSize = new Size(shapeDef.Width, shapeDef.Height);                             _originalRotation = shapeDef.Angle;                              // 如果是旋转手柄，记录起始角度                             if (hitHandleType == Rendering.HandleType.Rotate)                             {                                 _rotateStartAngle = shapeDef.Angle;                                 var center = new Point(shapeDef.CenterX, shapeDef.CenterY);                                 _rotateStartMouseAngle = CalculateMouseAngle(center, position);                             }                         }                          _viewModel.StatusMessage = $"正在拖动 {hitHandleType} 手柄";                         e.Handled = true;                         return;                     }                 }             }              // ========== 检测区域命中 ==========             var hitRegion = HitTestRegion(position);             if (hitRegion != null)             {                 SelectRegion(hitRegion);                 _isDragging = true;                 _dragStartPoint = position;                 e.Handled = true;             }             else             {                 DeselectAll();             }         }              private void ImageControl_CanvasMouseLeftButtonUp(object? sender, ImageMouseEventArgs e)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[CanvasMouseLeftButtonUp] MouseUp事件 | InstanceId={_controlInstanceId} | Source=ImageControl | Position={e.ImagePosition:F1}",                 "RegionEditorControl");              FinishInteraction();         }          private void ImageControl_ViewTransformed(object? sender, ViewTransformEventArgs e)         {             // ★ 关键诊断：仅当缩放值变化时记录（低频）             VisionLogger.Instance.Log(LogLevel.Info,                 $"[ViewTransformed] zoom={e:F3} | offset=({e.OffsetX:F1},{e.OffsetY:F1}) | 将同步到渲染器",                 "RegionEditorControl");              // 同步渲染器缩放参数（仅用于线宽/虚线间距反除缩放）             // 注意：不传 offset！OverlayCanvas 在 ImageContainer 内部，             // ImageContainer 自身有 TranslateTransform，再叠加 offset 会导致双重偏移             _renderer?.SetViewportTransform(e.Zoom, new Point(0, 0));              UpdateRegionOverlay();         }          /// <summary>         /// 窗口级 MouseUp 事件处理（兜底：处理鼠标移出 MainCanvas 后松开的边界情况）         /// </summary>         private void Window_MouseLeftButtonUp(object sender, MouseButtonEventArgs e)         {             // 无交互状态时忽略窗口级MouseUp，避免点击窗口其他区域产生无关日志             if (!_isDrawing && !_isDragging && !_isDraggingHandle)             {                 return;             }              VisionLogger.Instance.Log(LogLevel.Info,                 $"[Window_MouseLeftButtonUp] MouseUp事件 | InstanceId={_controlInstanceId} | Source=Window | _isDrawing={_isDrawing} | _isDragging={_isDragging} | _isDraggingHandle={_isDraggingHandle}",                 "RegionEditorControl");              FinishInteraction();         }          /// <summary>         /// 窗口级右键事件处理（多边形撤销顶点）         /// </summary>         private void Window_MouseRightButtonDown(object sender, MouseButtonEventArgs e)         {             if (!_isDrawingPolygon || _currentTool != ShapeType.Polygon                 || _polygonPoints.Count <= 0)                 return;              VisionLogger.Instance.Log(LogLevel.Info,                 $"[Window_MouseRightButtonDown] 右键触发多边形撤销 | InstanceId={_controlInstanceId} | 顶点数={_polygonPoints.Count}",                 "RegionEditorControl");              _polygonPoints.RemoveAt(_polygonPoints.Count - 1);             SyncPolygonToShapeDef();             if (_polygonPoints.Count == 0)             {                 _isDrawingPolygon = false;                 if (_currentDrawingRegion != null)                     ReleaseRegionIndex(_currentDrawingRegion.Name);                 _currentDrawingRegion = null;             }             ClearRubberBand();             if (_polygonPoints.Count >= 1 && _currentDrawingRegion != null)             {                 // 插入上次鼠标位置作为临时点，避免预览跳变                 if (_currentDrawingRegion.Parameters is ShapeParameters shapeDef)                 {                     shapeDef.Points.Add(new Point2D(_lastMouseImagePosition.X, _lastMouseImagePosition.Y));                     UpdateSingleRegionFast(_currentDrawingRegion);                     shapeDef.Points.RemoveAt(shapeDef.Points.Count - 1);                 }             }             else if (_polygonPoints.Count == 0)                 UpdateRegionOverlay();  // 全量重建，清除残留名称标签             _viewModel.StatusMessage = _polygonPoints.Count > 0                 ? $"多边形顶点: {_polygonPoints.Count}"                 : "已取消多边形绘制";             e.Handled = true;         }          private void FinishInteraction()         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[FinishInteraction] 调用 FinishInteraction | InstanceId={_controlInstanceId} | _isDrawing={_isDrawing} | _currentDrawingRegion={_currentDrawingRegion?.Name ?? "null"} | _isDrawingPolygon={_isDrawingPolygon}",                 "RegionEditorControl");              // ★ 多边形仍在绘制中（未完成），不清理状态             if (_isDrawingPolygon)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[FinishInteraction] 多边形仍在绘制中，跳过清理 | InstanceId={_controlInstanceId} | 顶点数={_polygonPoints.Count}",                     "RegionEditorControl");                  // 多边形非最终完成时，清理橡皮筋线但不重置 _isDrawing/_currentDrawingRegion                 ClearRubberBand();                 UpdateRegionOverlay();                 return;             }              if (_isDrawing && _currentDrawingRegion != null)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[FinishInteraction] 完成绘制 | InstanceId={_controlInstanceId} | Region={_currentDrawingRegion.Name} | IsPreview={_currentDrawingRegion.IsPreview} | _nextRegionIndex={_nextRegionIndex}",                     "RegionEditorControl");                  // 完成绘制，设置预览状态为 false                 _currentDrawingRegion.IsPreview = false;                  var shapeDef = _currentDrawingRegion.Parameters as ShapeParameters;                 if (shapeDef != null)                 {                     // 统一使用大尺寸算法，并对长宽增加限制：任意尺寸太小都不生成区域                     // 矩形和旋转矩形：最小宽度和高度都是10像素，同时满足面积≥100                     bool isValid = _currentTool switch                     {                         ShapeType.Rectangle or ShapeType.RotatedRectangle =>                             shapeDef.Width >= 10 &&                             shapeDef.Height >= 10 &&                             shapeDef.Width * shapeDef.Height >= 100,                         ShapeType.Circle =>                             shapeDef.Radius >= 5.64 && // 面积≥100对应的半径                             Math.PI * shapeDef.Radius * shapeDef.Radius >= 100,                         ShapeType.Line => shapeDef.GetLineLength() >= 10,                         ShapeType.Polygon => shapeDef.Points.Count >= 3,                         _ => false                     };                      VisionLogger.Instance.Log(LogLevel.Info,                         $"[FinishInteraction] 验证区域尺寸 | InstanceId={_controlInstanceId} | Region={_currentDrawingRegion.Name} | Width={shapeDef.Width:F2} | Height={shapeDef.Height:F2} | IsValid={isValid}",                         "RegionEditorControl");                      if (isValid)                     {                         _viewModel.Regions.Add(_currentDrawingRegion);                         _viewModel.SelectedRegion = _currentDrawingRegion;                         _viewModel.StatusMessage = $"已创建 {_currentTool} 区域";                         RegionDataChanged?.Invoke(this, _currentDrawingRegion);                          // ★ 诊断日志：新建区域后的完整状态                         var allRegionNames = string.Join(", ", _viewModel.Regions.Select(r => $"{r.Name}(Id={r.Id:B},IsVisible={r.IsVisible})"));                         VisionLogger.Instance.Log(LogLevel.Success,                             $"[FinishInteraction] 区域已添加到集合 | InstanceId={_controlInstanceId} | Region={_currentDrawingRegion.Name}(Id={_currentDrawingRegion.Id:B}) | TotalRegions={_viewModel.Regions.Count} | Regions=[{allRegionNames}]",                             "RegionEditorControl");                     }                     else                     {                         _viewModel.StatusMessage = "区域太小，已忽略";                          VisionLogger.Instance.Log(LogLevel.Warning,                             $"[FinishInteraction] 区域太小，已忽略 | InstanceId={_controlInstanceId} | Region={_currentDrawingRegion.Name}",                             "RegionEditorControl");                     }                 }             }              ClearRubberBand();             _isDrawing = false;             _isDragging = false;             _isDraggingHandle = false;             _currentDrawingRegion = null;              // 清理ROI编辑器风格的手柄状态             _activeHandleType = Rendering.HandleType.None;             _originalShapeDefinition = null;             _rotateStartAngle = null;             _rotateStartMouseAngle = null;              UpdateRegionOverlay();              VisionLogger.Instance.Log(LogLevel.Info,                 $"[FinishInteraction] 清理完成 | InstanceId={_controlInstanceId} | _isDrawing={_isDrawing} | _currentDrawingRegion={_currentDrawingRegion?.Name ?? "null"}",                 "RegionEditorControl");         }          #endregion          #region 绘制和渲染          private void UpdateDrawingPreview(Point currentPosition)         {             if (_currentDrawingRegion?.Parameters is not ShapeParameters shapeDef)                 return;              // Log preview update (every 10 times)             if (_previewLogCount++ % 10 == 0)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[UpdateDrawingPreview] Count={_previewLogCount} | Position={currentPosition:F1} | Tool={_currentTool}",                     "RegionEditorControl");             }              var dx = currentPosition.X - _startPoint.X;             var dy = currentPosition.Y - _startPoint.Y;              switch (_currentTool)             {                 case ShapeType.Rectangle:                 case ShapeType.RotatedRectangle:                     shapeDef.CenterX = _startPoint.X + dx / 2;                     shapeDef.CenterY = _startPoint.Y + dy / 2;                     shapeDef.Width = Math.Abs(dx);                     shapeDef.Height = Math.Abs(dy);                     break;                  case ShapeType.Circle:                     var radius = Math.Sqrt(dx * dx + dy * dy);                     shapeDef.Radius = radius;                     shapeDef.Width = radius * 2;                     shapeDef.Height = radius * 2;                     break;                  case ShapeType.Line:                     shapeDef.EndX = currentPosition.X;                     shapeDef.EndY = currentPosition.Y;                     break;             }         }          private void MoveRegion(RegionData region, Vector offset)         {             if (region.Parameters is ShapeParameters shapeDef)             {                 shapeDef.CenterX += offset.X;                 shapeDef.CenterY += offset.Y;                 shapeDef.StartX += offset.X;                 shapeDef.StartY += offset.Y;                 shapeDef.EndX += offset.X;                 shapeDef.EndY += offset.Y;                  // 移动多边形顶点                 for (int i = 0; i < shapeDef.Points.Count; i++)                 {                     var pt = shapeDef.Points[i];                     shapeDef.Points[i] = new Point2D(pt.X + offset.X, pt.Y + offset.Y);                 }                  region.MarkModified();                 RegionDataChanged?.Invoke(this, region);             }         }          #region 多边形辅助方法          /// <summary>         /// 将 _polygonPoints 同步到 ShapeParameters.Points         /// </summary>         private void SyncPolygonToShapeDef()         {             if (_currentDrawingRegion?.Parameters is ShapeParameters shapeDef)             {                 shapeDef.Points.Clear();                 foreach (var pt in _polygonPoints)                     shapeDef.Points.Add(new Point2D(pt.X, pt.Y));             }         }          /// <summary>         /// 绘制多边形橡皮筋线（从最后一个顶点到鼠标位置）         /// </summary>         private void DrawPolygonRubberBand(Point mousePosition)         {             var canvas = OverlayCanvas;             if (canvas == null || _polygonPoints.Count == 0) return;              ClearRubberBand();              var zoom = _mainImageControl?.Zoom ?? 1.0;             var lastPoint = _polygonPoints[_polygonPoints.Count - 1];              // 实线：最后一个顶点 -> 鼠标位置             var line = new System.Windows.Shapes.Line             {                 X1 = lastPoint.X, Y1 = lastPoint.Y,                 X2 = mousePosition.X, Y2 = mousePosition.Y,                 Stroke = Brushes.DodgerBlue,                 StrokeThickness = 2.0 / zoom,                 Tag = RubberBandTag             };             Canvas.SetZIndex(line, 50);             canvas.Children.Add(line);              // 小圆点：鼠标位置             var dotSize = 6.0 / zoom;             var dot = new Ellipse             {                 Width = dotSize, Height = dotSize,                 Fill = Brushes.DodgerBlue, Tag = RubberBandTag             };             Canvas.SetLeft(dot, mousePosition.X - dotSize / 2);             Canvas.SetTop(dot, mousePosition.Y - dotSize / 2);             Canvas.SetZIndex(dot, 50);             canvas.Children.Add(dot);         }          /// <summary>         /// 清除多边形橡皮筋线         /// </summary>         private void ClearRubberBand()         {             var canvas = OverlayCanvas;             if (canvas == null) return;             var toRemove = canvas.Children                 .OfType<FrameworkElement>()                 .Where(e => e.Tag as string == RubberBandTag)                 .ToList();             foreach (var item in toRemove)                 canvas.Children.Remove(item);         }          #endregion          /// <summary>         /// 根据手柄类型更新形状         /// </summary>         private void UpdateShapeByHandle(RegionData region, Rendering.HandleType handleType, double dx, double dy)         {             if (region.Parameters is not ShapeParameters shapeDef)                 return;              switch (shapeDef.ShapeType)             {                 case ShapeType.Rectangle:                     // 使用ResizeRectangleFromCorner和ResizeRectangleFromEdge方法                     // 这些方法在HandleShapeEdit中调用                     break;                 case ShapeType.RotatedRectangle:                     // 旋转矩形在HandleShapeEdit中通过HandleRotatedRectangleResize处理                     break;                 case ShapeType.Circle:                     UpdateCircleByHandle(shapeDef, handleType, dx, dy);                     break;                 case ShapeType.Line:                     UpdateLineByHandle(shapeDef, handleType, dx, dy);                     break;             }              region.MarkModified();             RegionDataChanged?.Invoke(this, region);         }          /// <summary>         /// 更新矩形形状（通过手柄，使用原始状态避免累积误差）         /// </summary>         private void UpdateRectangleByHandle(ShapeParameters shapeDef, Rendering.HandleType handleType, double dx, double dy)         {             // 此方法已弃用，现在使用ResizeRectangleFromCorner和ResizeRectangleFromEdge方法             // 这些方法使用原始状态保存机制，避免累积误差         }          /// <summary>         /// 将角度规范化到[-180°, 180°]范围         /// </summary>         private static double NormalizeAngle(double angle)         {             angle = angle % 360;             if (angle < 0) angle += 360;             if (angle > 180) angle -= 360;             return angle;         }          /// <summary>         /// 更新圆形形状（通过手柄）         /// </summary>         private void UpdateCircleByHandle(ShapeParameters shapeDef, Rendering.HandleType handleType, double dx, double dy)         {             switch (handleType)             {                 case Rendering.HandleType.Center:                     // 中心手柄用于拖动整个圆形                     shapeDef.CenterX += dx;                     shapeDef.CenterY += dy;                     break;                 default:                     // 圆形手柄用于调整半径                     var delta = Math.Sqrt(dx * dx + dy * dy);                     switch (handleType)                     {                         case Rendering.HandleType.Top:                             shapeDef.Radius += dy; // 向上拖动减小半径                             break;                         case Rendering.HandleType.Bottom:                             shapeDef.Radius += dy; // 向下拖动增大半径                             break;                         case Rendering.HandleType.Left:                             shapeDef.Radius += dx; // 向左拖动减小半径                             break;                         case Rendering.HandleType.Right:                             shapeDef.Radius += dx; // 向右拖动增大半径                             break;                     }                      // 确保半径不为负                     if (shapeDef.Radius < 5) shapeDef.Radius = 5;                      // 同步更新 Width 和 Height                     shapeDef.Width = shapeDef.Radius * 2;                     shapeDef.Height = shapeDef.Radius * 2;                     break;             }         }          /// <summary>         /// 更新直线形状（通过手柄）         /// </summary>         private void UpdateLineByHandle(ShapeParameters shapeDef, Rendering.HandleType handleType, double dx, double dy)         {             switch (handleType)             {                 case Rendering.HandleType.LineStart:                     shapeDef.StartX += dx;                     shapeDef.StartY += dy;                     break;                 case Rendering.HandleType.LineEnd:                     shapeDef.EndX += dx;                     shapeDef.EndY += dy;                     break;             }         }          /// <summary>         /// ROI编辑器风格的手柄编辑处理         /// 参考ROI编辑器的编辑操作逻辑（ROIImageEditor.xaml.cs 1461-1816行）         /// </summary>         private void HandleShapeEdit(ShapeParameters shape, Point currentPosition)         {             var delta = currentPosition - _handleDragStartPoint;              // 多边形顶点拖拽             if (shape.ShapeType == ShapeType.Polygon && _activeHandleType == Rendering.HandleType.PolygonVertex)             {                 if (_activeVertexIndex >= 0 && _activeVertexIndex < shape.Points.Count)                 {                     shape.Points[_activeVertexIndex] = new Point2D(                         currentPosition.X, currentPosition.Y);                 }                 return;             }              // 直线端点调整             if (shape.ShapeType == ShapeType.Line)             {                 HandleLineEndpoint(shape, currentPosition);                 return;             }              // 圆形半径调整             if (shape.ShapeType == ShapeType.Circle)             {                 HandleCircleResize(shape, currentPosition);                 return;             }              // 旋转矩形调整             if (shape.ShapeType == ShapeType.RotatedRectangle)             {                 if (_activeHandleType == Rendering.HandleType.Rotate)                 {                     HandleRotate(shape, currentPosition);                 }                 else                 {                     HandleRotatedRectangleResize(shape, currentPosition, delta);                 }                 return;             }              // 普通矩形调整             if (shape.ShapeType == ShapeType.Rectangle)             {                 switch (_activeHandleType)                 {                     case Rendering.HandleType.TopLeft:                         ResizeRectangleFromCorner(shape, delta, true, true);                         break;                     case Rendering.HandleType.TopRight:                         ResizeRectangleFromCorner(shape, delta, false, true);                         break;                     case Rendering.HandleType.BottomLeft:                         ResizeRectangleFromCorner(shape, delta, true, false);                         break;                     case Rendering.HandleType.BottomRight:                         ResizeRectangleFromCorner(shape, delta, false, false);                         break;                     case Rendering.HandleType.Top:                         ResizeRectangleFromEdge(shape, delta, true, true);                         break;                     case Rendering.HandleType.Bottom:                         ResizeRectangleFromEdge(shape, delta, true, false);                         break;                     case Rendering.HandleType.Left:                         ResizeRectangleFromEdge(shape, delta, false, true);                         break;                     case Rendering.HandleType.Right:                         ResizeRectangleFromEdge(shape, delta, false, false);                         break;                 }             }              // 触发变更事件             if (_selectedRegion != null)             {                 _selectedRegion.MarkModified();                 RegionDataChanged?.Invoke(this, _selectedRegion);             }         }          /// <summary>         /// 处理旋转操作（参考ROI编辑器HandleRotate 1792-1816行）         /// </summary>         private void HandleRotate(ShapeParameters shape, Point currentPosition)         {             var center = new Point(shape.CenterX, shape.CenterY);              // 保存旋转开始时的状态（第一次调用时）             if (_rotateStartAngle == null)             {                 _rotateStartAngle = shape.Angle;                 _rotateStartMouseAngle = CalculateMouseAngle(center, _handleDragStartPoint);             }              // 计算当前鼠标角度             var currentMouseAngle = CalculateMouseAngle(center, currentPosition);              // 计算角度增量             var deltaAngle = currentMouseAngle - _rotateStartMouseAngle.Value;              // 应用角度增量（使用RotatedRectangleHelper.NormalizeAngle）             shape.Angle = RotatedRectangleHelper.NormalizeAngle(_rotateStartAngle.Value + deltaAngle);         }          /// <summary>         /// 计算鼠标相对于中心的图像坐标系角度         /// </summary>         private double CalculateMouseAngle(Point center, Point mousePos)         {             // 计算鼠标相对于中心的数学角度             // Math.Atan2返回数学角度：逆时针为正，0°向右             var mathAngle = Math.Atan2(mousePos.Y - center.Y, mousePos.X - center.X) * 180 / Math.PI;              // 转换为图像坐标系角度（顺时针为正，0°向下）             // 公式：imageAngle = -mathAngle + 90             return -mathAngle + 90;         }          /// <summary>         /// 处理旋转矩形大小调整（使用坐标变换，参考ROI编辑器）         /// </summary>         private void HandleRotatedRectangleResize(ShapeParameters shape, Point currentPosition, Vector delta)         {             if (_originalShapeDefinition == null) return;              // 1. 将世界坐标系的 delta 转换为局部坐标系的 delta             var localDelta = WorldToLocalDelta(delta, _originalRotation);              // 2. 计算原始矩形的四个角点（局部坐标，原点在中心）             var corners = GetLocalCorners(_originalSize.Width, _originalSize.Height);              // 3. 根据拖动的手柄计算新的角点位置             var newCorners = CalculateNewCorners(corners, localDelta, _activeHandleType);              // 4. 从新角点计算新的尺寸和中心             var (newWidth, newHeight, newCenterLocal) = CalculateFromCorners(newCorners);              // 5. 将新中心从局部坐标转换回世界坐标             var newCenterWorld = LocalToWorldPoint(newCenterLocal, _originalPosition, _originalRotation);              // 6. 应用新的状态             shape.Width = newWidth;             shape.Height = newHeight;             shape.CenterX = newCenterWorld.X;             shape.CenterY = newCenterWorld.Y;         }          /// <summary>         /// 将世界坐标系的 delta 转换为局部坐标系的 delta（参考ROI编辑器）         /// </summary>         private Vector WorldToLocalDelta(Vector worldDelta, double rotation)         {             // 将角度转换为弧度             var angle = -rotation * Math.PI / 180;             var cos = Math.Cos(angle);             var sin = Math.Sin(angle);              // 使用逆旋转矩阵：local = transpose(R) * world             return new Vector(                 worldDelta.X * cos + worldDelta.Y * sin,                 -worldDelta.X * sin + worldDelta.Y * cos);         }          /// <summary>         /// 将局部坐标系的点转换为世界坐标系的点（参考ROI编辑器）         /// </summary>         private Point LocalToWorldPoint(Point localPoint, Point center, double rotation)         {             // 将角度转换为弧度             var angle = -rotation * Math.PI / 180;             var cos = Math.Cos(angle);             var sin = Math.Sin(angle);              return new Point(                 center.X + localPoint.X * cos - localPoint.Y * sin,                 center.Y + localPoint.X * sin + localPoint.Y * cos);         }          /// <summary>         /// 获取矩形四个角点（局部坐标，原点在中心）         /// </summary>         private Point[] GetLocalCorners(double width, double height)         {             var hw = width / 2;             var hh = height / 2;             return new Point[]             {                 new Point(-hw, -hh), // TopLeft                 new Point( hw, -hh), // TopRight                 new Point( hw,  hh), // BottomRight                 new Point(-hw,  hh)  // BottomLeft             };         }          /// <summary>         /// 根据拖动的手柄计算新的角点位置（固定对角锚点模式）         /// </summary>         private Point[] CalculateNewCorners(Point[] originalCorners, Vector delta, Rendering.HandleType handle)         {             var newCorners = (Point[])originalCorners.Clone();              switch (handle)             {                 case Rendering.HandleType.TopLeft:                     // TopLeft 移动，BottomRight 固定                     newCorners[0] = new Point(                         originalCorners[0].X + delta.X,                         originalCorners[0].Y + delta.Y);                     // TopRight 和 BottomLeft 跟随变化（保持矩形形状）                     newCorners[1] = new Point(originalCorners[1].X, newCorners[0].Y);                     newCorners[3] = new Point(newCorners[0].X, originalCorners[3].Y);                     break;                  case Rendering.HandleType.TopRight:                     // TopRight 移动，BottomLeft 固定                     newCorners[1] = new Point(                         originalCorners[1].X + delta.X,                         originalCorners[1].Y + delta.Y);                     newCorners[0] = new Point(originalCorners[0].X, newCorners[1].Y);                     newCorners[2] = new Point(newCorners[1].X, originalCorners[2].Y);                     break;                  case Rendering.HandleType.BottomRight:                     // BottomRight 移动，TopLeft 固定                     newCorners[2] = new Point(                         originalCorners[2].X + delta.X,                         originalCorners[2].Y + delta.Y);                     newCorners[1] = new Point(newCorners[2].X, originalCorners[1].Y);                     newCorners[3] = new Point(originalCorners[3].X, newCorners[2].Y);                     break;                  case Rendering.HandleType.BottomLeft:                     // BottomLeft 移动，TopRight 固定                     newCorners[3] = new Point(                         originalCorners[3].X + delta.X,                         originalCorners[3].Y + delta.Y);                     newCorners[0] = new Point(newCorners[3].X, originalCorners[0].Y);                     newCorners[2] = new Point(originalCorners[2].X, newCorners[3].Y);                     break;                  case Rendering.HandleType.Top:                     // 只改变高度，固定 Bottom 边                     var newTop = originalCorners[0].Y + delta.Y;                     newCorners[0] = new Point(originalCorners[0].X, newTop);                     newCorners[1] = new Point(originalCorners[1].X, newTop);                     break;                  case Rendering.HandleType.Bottom:                     // 只改变高度，固定 Top 边                     var newBottom = originalCorners[2].Y + delta.Y;                     newCorners[2] = new Point(originalCorners[2].X, newBottom);                     newCorners[3] = new Point(originalCorners[3].X, newBottom);                     break;                  case Rendering.HandleType.Left:                     // 只改变宽度，固定 Right 边                     var newLeft = originalCorners[0].X + delta.X;                     newCorners[0] = new Point(newLeft, originalCorners[0].Y);                     newCorners[3] = new Point(newLeft, originalCorners[3].Y);                     break;                  case Rendering.HandleType.Right:                     // 只改变宽度，固定 Left 边                     var newRight = originalCorners[1].X + delta.X;                     newCorners[1] = new Point(newRight, originalCorners[1].Y);                     newCorners[2] = new Point(newRight, originalCorners[2].Y);                     break;             }              return newCorners;         }          /// <summary>         /// 从四个角点计算宽度、高度和中心（局部坐标）         /// </summary>         private (double width, double height, Point center) CalculateFromCorners(Point[] corners)         {             var width = corners[1].X - corners[0].X;             var height = corners[2].Y - corners[0].Y;              // 确保最小尺寸，取绝对值             width = Math.Max(10, Math.Abs(width));             height = Math.Max(10, Math.Abs(height));              var center = new Point(                 (corners[0].X + corners[2].X) / 2,                 (corners[0].Y + corners[2].Y) / 2);              return (width, height, center);         }          /// <summary>         /// 处理圆形半径调整（参考ROI编辑器HandleCircleResize 1473-1477行）         /// </summary>         private void HandleCircleResize(ShapeParameters shape, Point currentPosition)         {             var center = new Point(shape.CenterX, shape.CenterY);              // 计算从中心到鼠标的距离作为新半径             var dx = currentPosition.X - center.X;             var dy = currentPosition.Y - center.Y;             var newRadius = Math.Sqrt(dx * dx + dy * dy);              if (newRadius < 5) newRadius = 5;              shape.Radius = newRadius;                          // 同步更新 Width 和 Height，确保手柄位置正确             shape.Width = newRadius * 2;             shape.Height = newRadius * 2;         }          /// <summary>         /// 处理直线端点调整（参考ROI编辑器HandleLineResize 1466-1470行）         /// </summary>         private void HandleLineEndpoint(ShapeParameters shape, Point currentPosition)         {             if (_activeHandleType == Rendering.HandleType.LineStart)             {                 shape.StartX = currentPosition.X;                 shape.StartY = currentPosition.Y;             }             else if (_activeHandleType == Rendering.HandleType.LineEnd)             {                 shape.EndX = currentPosition.X;                 shape.EndY = currentPosition.Y;             }         }          /// <summary>         /// 从角落调整矩形（不对称编辑 - 固定对角点模式）         /// 参考ROI编辑器旋转矩形的HandleRotatedRectangleResize逻辑         /// </summary>         private void ResizeRectangleFromCorner(ShapeParameters shape, Vector delta, bool isLeft, bool isTop)         {             if (_originalShapeDefinition == null) return;              var original = _originalShapeDefinition;              // 计算原始矩形的四个角点（局部坐标，原点在中心）             var hw = original.Width / 2;             var hh = original.Height / 2;             var corners = new Point[]             {                 new Point(-hw, -hh), // TopLeft                 new Point( hw, -hh), // TopRight                 new Point( hw,  hh), // BottomRight                 new Point(-hw,  hh)  // BottomLeft             };              // 根据拖动的角点计算新的角点位置（固定对角锚点模式）             Point[] newCorners;              // 确定拖动的手柄类型             if (isLeft && isTop) // TopLeft             {                 // TopLeft 移动，BottomRight 固定                 newCorners = new Point[]                 {                     new Point(corners[0].X + delta.X, corners[0].Y + delta.Y),                     new Point(corners[1].X, corners[0].Y + delta.Y),                     new Point(corners[2].X, corners[2].Y),                     new Point(corners[0].X + delta.X, corners[3].Y)                 };             }             else if (!isLeft && isTop) // TopRight             {                 // TopRight 移动，BottomLeft 固定                 newCorners = new Point[]                 {                     new Point(corners[0].X, corners[0].Y + delta.Y),                     new Point(corners[1].X + delta.X, corners[1].Y + delta.Y),                     new Point(corners[1].X + delta.X, corners[2].Y),                     new Point(corners[3].X, corners[3].Y)                 };             }             else if (isLeft && !isTop) // BottomLeft             {                 // BottomLeft 移动，TopRight 固定                 // TopLeft.X 跟随 BottomLeft.X，BottomRight.Y 跟随 BottomLeft.Y                 newCorners = new Point[]                 {                     new Point(corners[0].X + delta.X, corners[0].Y),                     new Point(corners[1].X, corners[1].Y),                     new Point(corners[2].X, corners[2].Y + delta.Y),                     new Point(corners[3].X + delta.X, corners[3].Y + delta.Y)                 };             }             else // BottomRight             {                 // BottomRight 移动，TopLeft 固定                 newCorners = new Point[]                 {                     new Point(corners[0].X, corners[0].Y),                     new Point(corners[1].X + delta.X, corners[1].Y),                     new Point(corners[2].X + delta.X, corners[2].Y + delta.Y),                     new Point(corners[3].X, corners[3].Y + delta.Y)                 };             }              // 从新角点计算新的尺寸和中心             var newWidth = Math.Max(10, newCorners[1].X - newCorners[0].X);             var newHeight = Math.Max(10, newCorners[2].Y - newCorners[0].Y);             var centerLocal = new Point(                 (newCorners[0].X + newCorners[2].X) / 2,                 (newCorners[0].Y + newCorners[2].Y) / 2);              // 将局部坐标转换为世界坐标             shape.Width = newWidth;             shape.Height = newHeight;             shape.CenterX = original.CenterX + centerLocal.X;             shape.CenterY = original.CenterY + centerLocal.Y;         }          /// <summary>         /// 从边缘调整矩形（参考ROI编辑器ResizeFromEdge 1760-1790行）         /// </summary>         /// <summary>         /// 从边缘调整矩形（非对称编辑 - 固定对边模式）         /// 使用与 ResizeRectangleFromCorner 相同的角点计算逻辑         /// </summary>         private void ResizeRectangleFromEdge(ShapeParameters shape, Vector delta, bool isVertical, bool isTopOrLeft)         {             if (_originalShapeDefinition == null) return;              var original = _originalShapeDefinition;              // 计算原始矩形的四个角点（局部坐标，原点在中心）             var hw = original.Width / 2;             var hh = original.Height / 2;             var corners = new Point[]             {                 new Point(-hw, -hh), // TopLeft                 new Point( hw, -hh), // TopRight                 new Point( hw,  hh), // BottomRight                 new Point(-hw,  hh)  // BottomLeft             };              // 根据拖动的边缘计算新的角点位置（固定对边模式）             Point[] newCorners;              if (isVertical)             {                 if (isTopOrLeft) // Top 边：移动 TopLeft 和 TopRight，Bottom 边固定                 {                     newCorners = new Point[]                     {                         new Point(corners[0].X, corners[0].Y + delta.Y), // TopLeft 移动                         new Point(corners[1].X, corners[1].Y + delta.Y), // TopRight 移动                         new Point(corners[2].X, corners[2].Y),           // BottomRight 固定                         new Point(corners[3].X, corners[3].Y)            // BottomLeft 固定                     };                 }                 else // Bottom 边：移动 BottomLeft 和 BottomRight，Top 边固定                 {                     newCorners = new Point[]                     {                         new Point(corners[0].X, corners[0].Y),           // TopLeft 固定                         new Point(corners[1].X, corners[1].Y),           // TopRight 固定                         new Point(corners[2].X, corners[2].Y + delta.Y), // BottomRight 移动                         new Point(corners[3].X, corners[3].Y + delta.Y)  // BottomLeft 移动                     };                 }             }             else             {                 if (isTopOrLeft) // Left 边：移动 TopLeft 和 BottomLeft，Right 边固定                 {                     newCorners = new Point[]                     {                         new Point(corners[0].X + delta.X, corners[0].Y), // TopLeft 移动                         new Point(corners[1].X, corners[1].Y),           // TopRight 固定                         new Point(corners[2].X, corners[2].Y),           // BottomRight 固定                         new Point(corners[3].X + delta.X, corners[3].Y)  // BottomLeft 移动                     };                 }                 else // Right 边：移动 TopRight 和 BottomRight，Left 边固定                 {                     newCorners = new Point[]                     {                         new Point(corners[0].X, corners[0].Y),           // TopLeft 固定                         new Point(corners[1].X + delta.X, corners[1].Y), // TopRight 移动                         new Point(corners[2].X + delta.X, corners[2].Y), // BottomRight 移动                         new Point(corners[3].X, corners[3].Y)            // BottomLeft 固定                     };                 }             }              // 从新角点计算新的尺寸和中心             var newWidth = Math.Max(10, newCorners[1].X - newCorners[0].X);             var newHeight = Math.Max(10, newCorners[2].Y - newCorners[0].Y);             var centerLocal = new Point(                 (newCorners[0].X + newCorners[2].X) / 2,                 (newCorners[0].Y + newCorners[2].Y) / 2);              // 将局部坐标转换为世界坐标             shape.Width = newWidth;             shape.Height = newHeight;             shape.CenterX = original.CenterX + centerLocal.X;             shape.CenterY = original.CenterY + centerLocal.Y;         }          private void UpdateRegionOverlay()         {             if (OverlayCanvas == null) return;              // ── 第一步：统一清除手柄 ──             // 无论后续走哪个渲染分支，先清除旧手柄，避免残留             Rendering.HandleRenderer.ClearHandles(OverlayCanvas);              // ── 第二步：渲染区域形状 ──             var regions = _viewModel?.Regions;             if (regions == null || regions.Count == 0)             {                 // 没有区域：清除画布内容，不需要手柄                 if (_renderer != null)                     _renderer.Render(new List<RegionRenderContext>(), new RegionRenderOptions { ShowLabels = true, ShowHandles = false });                 else                     OverlayCanvas.Children.Clear();                 return;             }              if (_renderer != null)             {                 // 主渲染路径：WpfShapeRenderer（对象池 + 增量更新）                 var contexts = BuildRenderContexts(regions);                  // 添加正在绘制的预览区域                 if (_isDrawing && _currentDrawingRegion?.Parameters is ShapeParameters previewShape)                     contexts.Add(CreateRenderContext(_currentDrawingRegion, previewShape, isPreview: true));                  _renderer.Render(contexts, new RegionRenderOptions { ShowLabels = true, ShowHandles = false });             }             else             {                 // 回退路径：传统逐个绘制                 OverlayCanvas.Children.Clear();                  foreach (var region in regions)                 {                     if (!region.IsVisible) continue;                     var shape = CreateRegionShape(region);                     if (shape != null)                         OverlayCanvas.Children.Add(shape);                     DrawRegionLabel(region);                 }                  if (_isDrawing && _currentDrawingRegion != null)                 {                     var previewShape = CreateRegionShape(_currentDrawingRegion, true);                     if (previewShape != null)                         OverlayCanvas.Children.Add(previewShape);                 }             }              // ── 第三步：绘制选中区域的编辑手柄 ──             if (_selectedRegion != null && !_isDrawing)                 DrawEditHandles(_selectedRegion);         }          /// <summary>         /// 从区域列表构建渲染上下文（过滤不可见和非 ShapeParameters 区域）         /// </summary>         private List<RegionRenderContext> BuildRenderContexts(IList<RegionData> regions)         {             var contexts = new List<RegionRenderContext>(regions.Count);              foreach (var region in regions)             {                 if (!region.IsVisible) continue;                 if (region.Parameters is not ShapeParameters shapeDef) continue;                  contexts.Add(CreateRenderContext(region, shapeDef, region.IsPreview));             }              return contexts;         }          /// <summary>         /// 创建渲染上下文         /// </summary>         private RegionRenderContext CreateRenderContext(RegionData region, ShapeParameters shape, bool isPreview = false)         {             // 日志监控（每次调用都记录，因为这个方法调用频率不高）             VisionLogger.Instance.Log(LogLevel.Info,                 $"[CreateRenderContext] RegionId={region.Id}, IsPreview={isPreview}, ShapeType={shape.ShapeType}",                 "RegionEditorControl");              var context = new RegionRenderContext             {                 Id = region.Id,                 ShapeType = shape.ShapeType,                 IsSelected = region == _selectedRegion,                 IsPreview = isPreview,                 IsVisible = true,                  // 几何参数                 Center = new Point(shape.CenterX, shape.CenterY),                 Width = shape.Width,                 Height = shape.Height,                 Angle = shape.Angle,                 Radius = shape.Radius,                 LineStart = new Point(shape.StartX, shape.StartY),                 LineEnd = new Point(shape.EndX, shape.EndY),                 PolygonPoints = shape.Points?.Select(p => new Point(p.X, p.Y)).ToList() ?? new List<Point>(),                  // 样式参数                 FillColor = Color.FromArgb(                     (byte)((shape.FillColorArgb >> 24) & 0xFF),                     (byte)((shape.FillColorArgb >> 16) & 0xFF),                     (byte)((shape.FillColorArgb >> 8) & 0xFF),                     (byte)(shape.FillColorArgb & 0xFF)                 ),                 StrokeColor = Color.FromArgb(                     (byte)((shape.StrokeColorArgb >> 24) & 0xFF),                     (byte)((shape.StrokeColorArgb >> 16) & 0xFF),                     (byte)((shape.StrokeColorArgb >> 8) & 0xFF),                     (byte)(shape.StrokeColorArgb & 0xFF)                 ),                 StrokeThickness = shape.StrokeThickness,                 Opacity = shape.Opacity,                  // 标签                 Label = region.Name             };              context.CalculateBounds();             return context;         }          /// <summary>         /// 绘制编辑手柄（ROI编辑器风格）         /// </summary>         private void DrawEditHandles(RegionData region)         {             // ★ 诊断日志：手柄绘制入口             VisionLogger.Instance.Log(LogLevel.Info,                 $"[DrawEditHandles] 入口 | Region={region.Name}(Id={region.Id:B}) | Parameters={region.Parameters?.GetType().Name ?? "null"} | IsShapeParams={region.Parameters is ShapeParameters} | OverlayCanvas={OverlayCanvas != null}",                 "RegionEditorControl");              if (region.Parameters is not ShapeParameters shapeDef || OverlayCanvas == null)             {                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[DrawEditHandles] 跳过手柄绘制 | Region={region.Name} | IsShapeParams={region.Parameters is ShapeParameters} | OverlayCanvas={OverlayCanvas != null}",                     "RegionEditorControl");                 return;             }              // 使用ROI编辑器的手柄渲染器创建手柄（反除缩放，使手柄在屏幕上视觉恒定）             CreateHandlesForShape(shapeDef);              if (_currentHandles != null && _currentHandles.Length > 0)             {                 // 使用ROI编辑器的手柄渲染器绘制手柄（传入缩放比例）                 var zoom = _mainImageControl?.Zoom ?? 1.0;                 Rendering.HandleRenderer.DrawHandles(OverlayCanvas, _currentHandles, shapeDef.ShapeType, zoom);             }         }          /// <summary>         /// 为形状创建ROI编辑器风格的手柄（强自适应 + 差异化）         /// </summary>         private void CreateHandlesForShape(ShapeParameters shape)         {             // 传入zoom，各手柄内部根据类型差异化计算尺寸             var zoom = _mainImageControl?.Zoom ?? 1.0;              // ★ 关键诊断：记录缩放信息             VisionLogger.Instance.Log(LogLevel.Info,                 $"[CreateHandlesForShape] zoom={zoom:F3}, ShapeType={shape.ShapeType}",                 "RegionEditorControl");              switch (shape.ShapeType)             {                 case ShapeType.Rectangle:                     var bounds = new Rect(                         shape.CenterX - shape.Width / 2,                         shape.CenterY - shape.Height / 2,                         shape.Width,                         shape.Height                     );                     _currentHandles = Rendering.HandleRenderer.CreateRectangleHandles(bounds, zoom);                     break;                  case ShapeType.Circle:                     var center = new Point(shape.CenterX, shape.CenterY);                     _currentHandles = Rendering.HandleRenderer.CreateCircleHandles(center, shape.Radius, zoom);                     break;                  case ShapeType.RotatedRectangle:                     var rotatedCenter = new Point(shape.CenterX, shape.CenterY);                     var corners = RotatedRectangleHelper.GetCorners(                         rotatedCenter,                         shape.Width,                         shape.Height,                         shape.Angle                     );                     _currentHandles = Rendering.HandleRenderer.CreateRotatedRectangleHandles(                         corners,                         shape.Angle,                         rotatedCenter,                         zoom,                         shape.Height                     );                     break;                  case ShapeType.Line:                     var startPoint = new Point(shape.StartX, shape.StartY);                     var endPoint = new Point(shape.EndX, shape.EndY);                     _currentHandles = Rendering.HandleRenderer.CreateLineHandles(startPoint, endPoint, zoom);                     break;                  case ShapeType.Polygon:                     _currentHandles = Rendering.HandleRenderer.CreatePolygonHandles(shape.Points, zoom);                     break;             }         }          /// <summary>         /// 计算旋转矩形的下边中点         /// </summary>         private Point CalculateRotatedRectBottomCenter(Point center, double height, double angle)         {             var angleRad = angle * Math.PI / 180;             var sin = Math.Sin(angleRad);             var cos = Math.Cos(angleRad);              return new Point(                 center.X + (height / 2) * sin,                 center.Y + (height / 2) * cos             );         }          /// <summary>         /// 在可视化树中向上查找指定类型的父级元素         /// </summary>         private static T? FindVisualParent<T>(DependencyObject? child) where T : DependencyObject         {             if (child == null)                 return null;              DependencyObject? parent = VisualTreeHelper.GetParent(child);             while (parent != null)             {                 if (parent is T result)                     return result;                 parent = VisualTreeHelper.GetParent(parent);             }             return null;         }          private Shape? CreateRegionShape(RegionData region, bool isPreview = false)         {             if (region.Parameters is not ShapeParameters shapeDef)                 return null;              // 使用ShapeRenderer创建形状（参考ROI编辑器）             var isSelected = region == _selectedRegion;             var shape = ShapeRenderer.CreateShape(shapeDef, isSelected, isPreview);              if (shape != null)             {                 // 根据shape.Tag获取位置信息                 var tag = shape.Tag;                 if (tag != null && tag.GetType().GetProperty("X") != null && tag.GetType().GetProperty("Y") != null)                 {                     var xProp = tag.GetType().GetProperty("X");                     var yProp = tag.GetType().GetProperty("Y");                     var x = (double?)xProp.GetValue(tag);                     var y = (double?)yProp.GetValue(tag);                      if (x.HasValue && y.HasValue)                     {                         Canvas.SetLeft(shape, x.Value);                         Canvas.SetTop(shape, y.Value);                     }                 }                 // 直线不需要Canvas定位             }              return shape;         }          private void DrawRegionLabel(RegionData region)         {             if (OverlayCanvas == null || string.IsNullOrEmpty(region.Name)) return;              var bounds = GetRegionBounds(region);             double labelTop = bounds.Top - 18;              if (labelTop < 0) labelTop = bounds.Bottom + 2;              var label = new TextBlock             {                 Text = region.Name,                 FontSize = 12,                 Foreground = Brushes.White,                 Background = new SolidColorBrush(Color.FromArgb(180, 0, 0, 0)),                 Padding = new Thickness(4, 2, 4, 2),                 Tag = region.Id             };              label.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));             double labelWidth = label.DesiredSize.Width;              double labelLeft = bounds.Left + (bounds.Width - labelWidth) / 2;             if (labelLeft < 0) labelLeft = 0;              Canvas.SetLeft(label, labelLeft);             Canvas.SetTop(label, labelTop);             OverlayCanvas.Children.Add(label);         }          private Rect GetRegionBounds(RegionData region)         {             if (region.Parameters is not ShapeParameters shapeDef)                 return Rect.Empty;              return shapeDef.ShapeType switch             {                 ShapeType.Rectangle => new Rect(                     shapeDef.CenterX - shapeDef.Width / 2,                     shapeDef.CenterY - shapeDef.Height / 2,                     shapeDef.Width,                     shapeDef.Height),                 ShapeType.RotatedRectangle => new Rect(                     shapeDef.CenterX - shapeDef.Width / 2,                     shapeDef.CenterY - shapeDef.Height / 2,                     shapeDef.Width,                     shapeDef.Height),                 ShapeType.Circle => new Rect(                     shapeDef.CenterX - shapeDef.Radius,                     shapeDef.CenterY - shapeDef.Radius,                     shapeDef.Radius * 2,                     shapeDef.Radius * 2),                 ShapeType.Line => new Rect(                     Math.Min(shapeDef.StartX, shapeDef.EndX),                     Math.Min(shapeDef.StartY, shapeDef.EndY),                     Math.Abs(shapeDef.EndX - shapeDef.StartX),                     Math.Abs(shapeDef.EndY - shapeDef.StartY)),                 _ => Rect.Empty             };         }          #endregion          #region 命中测试和选择          private RegionData? HitTestRegion(Point point)         {             // 从后往前测试（后绘制的在上面）             foreach (var region in _viewModel.Regions.Reverse())             {                 if (!region.IsVisible) continue;                  if (IsPointInRegion(point, region))                 {                     return region;                 }             }              return null;         }          private bool IsPointInRegion(Point point, RegionData region)         {             if (region.Parameters is not ShapeParameters shapeDef)                 return false;              return shapeDef.ShapeType switch             {                 ShapeType.Rectangle => IsPointInRectangle(point, shapeDef),                 ShapeType.RotatedRectangle => IsPointInRotatedRectangle(point, shapeDef),                 ShapeType.Circle => IsPointInCircle(point, shapeDef),                 ShapeType.Line => IsPointNearLine(point, shapeDef),                 ShapeType.Polygon => IsPointInPolygon(point, shapeDef),                 _ => false             };         }          /// <summary>         /// 判断点是否在矩形内（参考ROI编辑器使用GetBounds和Contains）         /// </summary>         private bool IsPointInRectangle(Point point, ShapeParameters shapeDef)         {             var bounds = new Rect(                 shapeDef.CenterX - shapeDef.Width / 2,                 shapeDef.CenterY - shapeDef.Height / 2,                 shapeDef.Width,                 shapeDef.Height             );             return bounds.Contains(point);         }          /// <summary>         /// 判断点是否在圆形内         /// </summary>         private bool IsPointInCircle(Point point, ShapeParameters shapeDef)         {             var distance = Math.Sqrt(                 Math.Pow(point.X - shapeDef.CenterX, 2) +                 Math.Pow(point.Y - shapeDef.CenterY, 2));             return distance <= shapeDef.Radius;         }          /// <summary>         /// 判断点是否在直线附近（10像素容差）         /// </summary>         private bool IsPointNearLine(Point point, ShapeParameters shapeDef)         {             return DistanceToLine(point,                 new Point(shapeDef.StartX, shapeDef.StartY),                 new Point(shapeDef.EndX, shapeDef.EndY)) < 10;         }          /// <summary>         /// 判断点是否在旋转矩形内（使用坐标变换法）         /// </summary>         private bool IsPointInRotatedRectangle(Point point, ShapeParameters shapeDef)         {             // 1. 将测试点平移到以矩形中心为原点             double dx = point.X - shapeDef.CenterX;             double dy = point.Y - shapeDef.CenterY;              // 2. 逆旋转角度（弧度），将点变换到矩形的本地坐标系             // 使用数学角度系统：逆时针为正             double angleRad = -shapeDef.Angle * Math.PI / 180.0;             double cos = Math.Cos(angleRad);             double sin = Math.Sin(angleRad);              // 3. 计算本地坐标（旋转后的坐标）             double localX = dx * cos - dy * sin;             double localY = dx * sin + dy * cos;              // 4. 判断是否在轴对齐矩形内             double halfW = shapeDef.Width / 2;             double halfH = shapeDef.Height / 2;              return Math.Abs(localX) <= halfW && Math.Abs(localY) <= halfH;         }          private double DistanceToLine(Point point, Point lineStart, Point lineEnd)         {             var dx = lineEnd.X - lineStart.X;             var dy = lineEnd.Y - lineStart.Y;             var length = Math.Sqrt(dx * dx + dy * dy);              if (length < 0.001) return Point.Subtract(point, lineStart).Length;              var t = Math.Max(0, Math.Min(1,                 ((point.X - lineStart.X) * dx + (point.Y - lineStart.Y) * dy) / (length * length)));              var projection = new Point(lineStart.X + t * dx, lineStart.Y + t * dy);             return Point.Subtract(point, projection).Length;         }          /// <summary>         /// 射线法判断点是否在多边形内         /// </summary>         private bool IsPointInPolygon(Point point, ShapeParameters shapeDef)         {             var points = shapeDef.Points;             if (points.Count < 3) return false;              bool inside = false;             int j = points.Count - 1;              for (int i = 0; i < points.Count; j = i++)             {                 var pi = new Point(points[i].X, points[i].Y);                 var pj = new Point(points[j].X, points[j].Y);                  if (((pi.Y > point.Y) != (pj.Y > point.Y)) &&                     (point.X < (pj.X - pi.X) * (point.Y - pi.Y) / (pj.Y - pi.Y) + pi.X))                 {                     inside = !inside;                 }             }              return inside;         }          private void SelectRegion(RegionData? region)         {             // ★ 诊断日志：选中区域             VisionLogger.Instance.Log(LogLevel.Info,                 $"[SelectRegion] 选中区域 | Region={region?.Name ?? "null"}(Id={region?.Id:B}) | Regions.Count={_viewModel.Regions.Count}",                 "RegionEditorControl");              // 取消旧区域的参数变更订阅             UnsubscribeShapeParameters(_selectedRegion);              _selectedRegion = region;             _viewModel.SelectedRegion = region;             UpdateRegionOverlay();              // 订阅新区域的参数变更（面板→画布自动同步）             SubscribeShapeParameters(region);              // 选中区域后，确保焦点回到区域编辑器，以接收键盘事件（如Delete删除区域）             // 因为选择区域是通过主窗口 ImageControl 的鼠标事件触发的，             // 点击主窗口会导致焦点离开调试窗口，需要在选中后拉回焦点             if (region != null)             {                 Keyboard.Focus(this);             }         }          private void DeselectAll()         {             // ★ 诊断日志：取消选中             VisionLogger.Instance.Log(LogLevel.Info,                 $"[DeselectAll] 取消所有选中 | _selectedRegion={_selectedRegion?.Name ?? "null"} | Regions.Count={_viewModel.Regions.Count}",                 "RegionEditorControl");              UnsubscribeShapeParameters(_selectedRegion);              _selectedRegion = null;             _viewModel.SelectedRegion = null;              // 清理ROI编辑器风格的手柄状态             _currentHandles = null;             _activeHandleType = Rendering.HandleType.None;             _originalShapeDefinition = null;             _rotateStartAngle = null;             _rotateStartMouseAngle = null;              UpdateRegionOverlay();         }          #region 形状参数变更订阅（面板→画布自动同步）          /// <summary>         /// 取消形状参数变更订阅         /// </summary>         private void UnsubscribeShapeParameters(RegionData? region)         {             if (region?.Parameters is ShapeParameters shape)             {                 shape.PropertyChanged -= OnShapeParametersChanged;                 if (shape.ShapeType == ShapeType.Polygon)                 {                     foreach (var pt in shape.Points)                         pt.PropertyChanged -= OnPolygonPointPropertyChanged;                     shape.Points.CollectionChanged -= OnPolygonPointsCollectionChanged;                 }             }         }          /// <summary>         /// 订阅形状参数变更（面板→画布自动同步）         /// PropertyChanged 处理 CenterX/Width/Radius 等属性，         /// Point2D.PropertyChanged + CollectionChanged 处理多边形顶点         /// </summary>         private void SubscribeShapeParameters(RegionData? region)         {             if (region?.Parameters is ShapeParameters shape)             {                 shape.PropertyChanged += OnShapeParametersChanged;                 if (shape.ShapeType == ShapeType.Polygon)                 {                     foreach (var pt in shape.Points)                         pt.PropertyChanged += OnPolygonPointPropertyChanged;                     shape.Points.CollectionChanged += OnPolygonPointsCollectionChanged;                 }             }         }          /// <summary>         /// 形状参数 PropertyChanged 回调（CenterX, Width, Radius 等 → 画布刷新）         /// </summary>         private void OnShapeParametersChanged(object? sender, PropertyChangedEventArgs e)         {             if (_selectedRegion != null)                 UpdateSingleRegionFast(_selectedRegion);         }          /// <summary>         /// 多边形顶点 Point2D.PropertyChanged 回调（X/Y 绑定变更 → 画布刷新）         /// </summary>         private void OnPolygonPointPropertyChanged(object? sender, PropertyChangedEventArgs e)         {             if (_selectedRegion != null)                 UpdateSingleRegionFast(_selectedRegion);         }          /// <summary>         /// 多边形 Points.CollectionChanged 回调（添加/删除/替换顶点后刷新画布 + 重新订阅）         /// </summary>         private void OnPolygonPointsCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)         {             // 新项订阅 PropertyChanged             if (e.NewItems != null)             {                 foreach (Point2D pt in e.NewItems)                     pt.PropertyChanged += OnPolygonPointPropertyChanged;             }             // 旧项取消订阅             if (e.OldItems != null)             {                 foreach (Point2D pt in e.OldItems)                     pt.PropertyChanged -= OnPolygonPointPropertyChanged;             }              if (_selectedRegion != null)                 UpdateSingleRegionFast(_selectedRegion);         }          #endregion          /// <summary>         /// 快速更新单个区域（用于拖动时的增量更新）         /// </summary>         private void UpdateSingleRegionFast(RegionData region)         {             if (_renderer == null)             {                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[UpdateSingleRegionFast] Renderer is null | Region={region.Name} | OverlayCanvas={OverlayCanvas != null}",                     "RegionEditorControl");                 return;             }              if (region.Parameters is not ShapeParameters shape)             {                 VisionLogger.Instance.Log(LogLevel.Warning,                     $"[UpdateSingleRegionFast] Invalid parameter type | Region={region.Name} | ParameterType={region.Parameters?.GetType().Name}",                     "RegionEditorControl");                 return;             }              // Log rendering (every 10 times)             if (_renderLogCount++ % 10 == 0)             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[UpdateSingleRegionFast] Count={_renderLogCount} | Region={region.Name} | IsPreview={region.IsPreview} | Shape={shape.GetType().Name}",                     "RegionEditorControl");             }              // 使用 region.IsPreview 自动识别预览状态             var context = CreateRenderContext(region, shape, region.IsPreview);             _renderer.UpdateRegion(context);              // 更新手柄位置（手柄独立于区域渲染）             if (region == _selectedRegion && OverlayCanvas != null)             {                 Rendering.HandleRenderer.ClearHandles(OverlayCanvas);  // 清理手柄                 DrawEditHandles(region);  // 绘制新的手柄             }         }          #endregion          #region ViewModel事件处理          private void OnViewModelPropertyChanged(object? sender, PropertyChangedEventArgs e)         {             // 监控关键属性变化             if (e.PropertyName == nameof(RegionEditorViewModel.IsDrawing))             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[OnViewModelPropertyChanged] IsDrawing 变化 | InstanceId={_controlInstanceId} | NewValue={_viewModel.IsDrawing} | _isDrawing={_isDrawing} | IsLoaded={IsLoaded} | IsVisible={IsVisible} | _currentDrawingRegion={_currentDrawingRegion?.Name ?? "null"}",                     "RegionEditorControl");             }             else if (e.PropertyName == nameof(RegionEditorViewModel.SelectedShapeType))             {                 VisionLogger.Instance.Log(LogLevel.Info,                     $"[OnViewModelPropertyChanged] SelectedShapeType 变化 | InstanceId={_controlInstanceId} | NewValue={_viewModel.SelectedShapeType}",                     "RegionEditorControl");             }         }          private void OnRegionChanged(object? sender, RegionChangedEventArgs e)         {             // ★ 诊断日志：RegionChanged 事件详情             var currentRegionNames = _viewModel?.Regions != null                 ? string.Join(", ", _viewModel.Regions.Select(r => $"{r.Name}(Id={r.Id:B},IsVisible={r.IsVisible})"))                 : "null";             VisionLogger.Instance.Log(LogLevel.Warning,                 $"[OnRegionChanged] ViewModel 触发 RegionChanged | InstanceId={_controlInstanceId} | RegionId={e.Region?.Id:B} | RegionName={e.Region?.Name ?? "null"} | ChangeType={e.ChangeType} | Regions.Count={_viewModel?.Regions?.Count ?? -1} | Regions=[{currentRegionNames}]",                 "RegionEditorControl");              try             {                 // 区域删除时释放索引到空洞池                 if (e.ChangeType == RegionChangeType.Removed && e.Region != null)                 {                     ReleaseRegionIndex(e.Region.Name);                 }                 // 清除所有区域时重置索引管理                 else if (e.ChangeType == RegionChangeType.Cleared)                 {                     _availableIndices.Clear();                     _nextRegionIndex = 1;                 }                  UpdateRegionOverlay();                 if (e.Region != null)                 {                     RegionDataChanged?.Invoke(this, e.Region);                 }             }             catch (Exception ex)             {                 VisionLogger.Instance.Log(LogLevel.Error,                     $"[OnRegionChanged] 区域变更处理失败 | InstanceId={_controlInstanceId} | Error={ex.Message}",                     "RegionEditorControl",                     ex);             }         }          #endregion          /// <summary>         /// 生成区域名称 - 空洞池优先，O(log n)         /// </summary>         /// <remarks>         /// 优先填充被删除区域释放的索引空洞，无空洞时递增。         /// 例如：已有 区域_1、区域_3，则新建 区域_2（填充空洞）         /// </remarks>         private string GenerateRegionName()         {             int nextIndex;             if (_availableIndices.Count > 0)             {                 // 空洞池非空，取最小索引                 nextIndex = _availableIndices.Min;                 _availableIndices.Remove(nextIndex);             }             else             {                 // 无空洞，递增                 nextIndex = _nextRegionIndex++;             }             return $"区域_{nextIndex}";         }          /// <summary>         /// 释放区域索引到空洞池 - 删除时调用，O(log n)         /// </summary>         private void ReleaseRegionIndex(string regionName)         {             if (regionName != null && regionName.StartsWith("区域_"))             {                 var indexPart = regionName.Substring(3);                 if (int.TryParse(indexPart, out var index) && index > 0)                 {                     _availableIndices.Add(index);                 }             }         }          /// <summary>         /// 根据已有区域初始化空洞池 - SetRegionsSource 时调用         /// </summary>         private void InitializeRegionIndexFromExisting()         {             _availableIndices.Clear();             _nextRegionIndex = 1;              var usedIndices = new HashSet<int>();             foreach (var region in _viewModel.Regions)             {                 if (region.Name != null && region.Name.StartsWith("区域_"))                 {                     var indexPart = region.Name.Substring(3);                     if (int.TryParse(indexPart, out var index) && index > 0)                     {                         usedIndices.Add(index);                     }                 }             }              if (usedIndices.Count == 0)                 return;              var maxIndex = usedIndices.Max();             _nextRegionIndex = maxIndex + 1;              // 扫描 1~max 之间的空洞             for (int i = 1; i <= maxIndex; i++)             {                 if (!usedIndices.Contains(i))                 {                     _availableIndices.Add(i);                 }             }         }          #region 形状按钮点击事件          /// <summary>         /// 选择按钮点击事件 - 进入选择/编辑模式         /// </summary>         private void OnSelectButtonClick(object sender, RoutedEventArgs e)         {             EnterSelectMode(sender as Button);         }          private void OnRectangleButtonClick(object sender, RoutedEventArgs e)         {             SelectShapeTool(ShapeType.Rectangle, sender as Button);         }          private void OnCircleButtonClick(object sender, RoutedEventArgs e)         {             SelectShapeTool(ShapeType.Circle, sender as Button);         }          private void OnRotatedRectangleButtonClick(object sender, RoutedEventArgs e)         {             SelectShapeTool(ShapeType.RotatedRectangle, sender as Button);         }          private void OnLineButtonClick(object sender, RoutedEventArgs e)         {             SelectShapeTool(ShapeType.Line, sender as Button);         }          private void OnPolygonButtonClick(object sender, RoutedEventArgs e)         {             _isDrawingPolygon = false;             SelectShapeTool(ShapeType.Polygon, sender as Button);         }          /// <summary>         /// 进入选择/编辑模式         /// </summary>         private void EnterSelectMode(Button? clickedButton)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[EnterSelectMode] 进入选择模式 | IsLoaded={IsLoaded} | IsVisible={IsVisible}",                 "RegionEditorControl");              // 确保处于绘制模式（启用编辑功能）             _viewModel.CurrentMode = RegionSourceMode.Drawing;              // 退出绘制状态，进入选择状态             _viewModel.IsDrawing = false;             _currentTool = ShapeType.Point; // Point 表示选择工具              VisionLogger.Instance.Log(LogLevel.Success,                 $"[EnterSelectMode] 已切换到选择模式 | CurrentMode={_viewModel.CurrentMode} | IsDrawing={_viewModel.IsDrawing} | CurrentTool={_currentTool}",                 "RegionEditorControl");              // 更新按钮高亮状态             UpdateShapeButtonHighlight(clickedButton);              // 更新状态消息             _viewModel.StatusMessage = "选择/编辑模式 - 点击区域可编辑，滚轮缩放，拖拽平移";         }          /// <summary>         /// 选择形状工具并开始绘制         /// </summary>         private void SelectShapeTool(ShapeType shapeType, Button? clickedButton)         {             VisionLogger.Instance.Log(LogLevel.Info,                 $"[SelectShapeTool] 选择形状工具 | ShapeType={shapeType} | IsLoaded={IsLoaded} | IsVisible={IsVisible}",                 "RegionEditorControl");              // 设置当前工具             _currentTool = shapeType;              // 切换到绘制模式             _viewModel.CurrentMode = RegionSourceMode.Drawing;             _viewModel.IsDrawing = true;              VisionLogger.Instance.Log(LogLevel.Success,                 $"[SelectShapeTool] 切换到绘制模式 | CurrentMode={_viewModel.CurrentMode} | IsDrawing={_viewModel.IsDrawing} | SelectedShapeType={shapeType}",                 "RegionEditorControl");              // 手动触发 IsDrawingMode 的 PropertyChanged 事件             // 因为 CurrentMode 的默认值已经是 Drawing，所以 setter 不会触发 PropertyChanged             _viewModel.NotifyIsDrawingModeChanged();              // 设置 SelectedShapeType（如果值变化，setter 会自动调用 UpdateParameters）             // 如果值相同，setter 不会调用 UpdateParameters，所以我们需要手动调用             var oldShapeType = _viewModel.SelectedShapeType;             _viewModel.SelectedShapeType = shapeType;              // 只有当形状类型未变化时，才手动调用 UpdateParameters             // 因为这种情况下 setter 不会调用 UpdateParameters             // 同时需要手动触发 SelectedShapeType 的 PropertyChanged 事件，以确保参数面板可见性更新             if (oldShapeType == shapeType)             {                 _viewModel.CallUpdateParameters();                 _viewModel.NotifySelectedShapeTypeChanged();             }              // 更新按钮高亮状态             UpdateShapeButtonHighlight(clickedButton);              // 更新状态消息             var shapeName = shapeType switch             {                 ShapeType.Rectangle => "矩形",                 ShapeType.Circle => "圆形",                 ShapeType.RotatedRectangle => "旋转矩形",                 ShapeType.Line => "直线",                 ShapeType.Polygon => "多边形",                 _ => shapeType.ToString()             };             _viewModel.StatusMessage = $"已选择 {shapeName} 工具，在图像上拖动绘制";         }          /// <summary>         /// 更新形状按钮高亮状态         /// </summary>         private void UpdateShapeButtonHighlight(Button? activeButton)         {             // 遍历所有形状按钮并重置样式             var shapeContainer = FindShapeContainer();             if (shapeContainer != null)             {                 foreach (var child in shapeContainer.Children)                 {                     if (child is Button button)                     {                         ResetShapeButtonStyle(button);                     }                 }             }              // 高亮选中按钮             if (activeButton != null)             {                 activeButton.Background = new SolidColorBrush(Color.FromRgb(232, 244, 252));                 activeButton.BorderBrush = new SolidColorBrush(Color.FromRgb(0, 102, 204));                 activeButton.BorderThickness = new Thickness(1.5);                  // 更新图标颜色                 UpdateIconColor(activeButton, Color.FromRgb(0, 102, 204));             }              _activeShapeButton = activeButton;         }          /// <summary>         /// 更新图标颜色         /// </summary>         private static void UpdateIconColor(Button button, Color color)         {             var brush = new SolidColorBrush(color);              if (button.Content is Shape shape)             {                 shape.Stroke = brush;                 if (shape.Fill != Brushes.Transparent)                 {                     shape.Fill = brush;                 }             }             else if (button.Content is Grid grid)             {                 foreach (var child in grid.Children)                 {                     if (child is Shape s)                     {                         s.Stroke = brush;                         if (s.Fill != Brushes.Transparent)                         {                             s.Fill = brush;                         }                     }                     else if (child is Path p)                     {                         p.Stroke = brush;                         if (p.Fill != Brushes.Transparent)                         {                             p.Fill = brush;                         }                     }                 }             }         }          /// <summary>         /// 查找形状选择区域容器         /// </summary>         private System.Windows.Controls.Panel? FindShapeContainer()         {             return ShapeButtonPanel;         }          /// <summary>         /// 查找可视化树中的子元素         /// </summary>         private static T? FindVisualChild<T>(DependencyObject parent, Func<T, bool>? condition = null) where T : DependencyObject         {             for (int i = 0; i < System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent); i++)             {                 var child = System.Windows.Media.VisualTreeHelper.GetChild(parent, i);                 if (child is T typedChild && (condition == null || condition(typedChild)))                 {                     return typedChild;                 }                  var result = FindVisualChild(child, condition);                 if (result != null)                 {                     return result;                 }             }             return null;         }          /// <summary>         /// 重置形状按钮样式         /// </summary>         private void ResetShapeButtonStyle(Button? button)         {             if (button == null) return;              button.Background = Brushes.Transparent;             button.BorderBrush = new SolidColorBrush(Color.FromRgb(224, 224, 224));             button.BorderThickness = new Thickness(1);              // 重置图标颜色             UpdateIconColor(button, Color.FromRgb(85, 85, 85));         }          #endregion          #region INotifyPropertyChanged          public event PropertyChangedEventHandler? PropertyChanged;          protected void OnPropertyChanged(string propertyName)         {             PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));         }          #endregion     } }